const $ = s => document.querySelector(s);
const $$ = s => [...document.querySelectorAll(s)];
let state = {business:{},customers:[],suppliers:[],products:[],invoices:[],invoice_items:[],payments:[],purchases:[],supplier_payments:[],expenses:[],quotations:[],warranties:[],recurring_templates:[],employees:[],payroll:[],payroll_payments:[],cash_entries:[],states:[]};
let activeView='dashboard';
const titles={dashboard:['Dashboard','A clear view of how your business is doing.'],invoices:['Invoices','Your billing and invoice history.'],customers:['Customers','Customer details and balances.'],items:['Items & services','Your saved products and service rates.'],payments:['Payments & dues','Track collections and pending payments.'],inventory:['Inventory','Stock levels, valuation and adjustments.'],purchases:['Purchases','Supplier bills, stock receipts and returns.'],suppliers:['Suppliers','Supplier contacts and balances.'],expenses:['Expenses','Record and review operating expenses.'],quotations:['Quotations','Estimates and accepted customer quotes.'],warranties:['Warranty register','Warranty periods, serial numbers and QR cards.'],recurring:['Recurring invoices','Repeat invoice templates and due schedules.'],cashflow:['Cash flow','Money received, money paid and cash movement.'],staff:['Staff & payroll','Employee records and salary management.'],assistant:['AI business assistant','Business questions and local smart insights.'],reports:['Reports','Sales, profit, expenses and balances.'],settings:['Business settings','Manage your business profile and local data.']};
const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format(Number(n||0));
const num=n=>Number(n||0).toLocaleString('en-IN',{maximumFractionDigits:2});
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateFmt=s=>s?new Date(s+'T00:00:00').toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'}):'—';
const isoLocal=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const today=()=>isoLocal(new Date());
const monthStart=()=>{const d=new Date();return isoLocal(new Date(d.getFullYear(),d.getMonth(),1));};
async function api(url,opts={}){let r;try{r=await fetch(url,{credentials:'same-origin',...opts,headers:{'Content-Type':'application/json',...(opts.headers||{})}});}catch(_){throw new Error('Cannot reach HisabFlow. Make sure run_hisabflow.bat is still running.');}const data=await r.json().catch(()=>({error:'Unexpected server response'}));if(r.status===401&&!url.startsWith('/api/auth/')){closeModal();showAuth('login','Your session has ended. Please sign in again.');}if(!r.ok)throw new Error(data.error||'Something went wrong');return data;}
async function reload(){state=await api('/api/state');renderAll();}
function toast(msg,type){const el=$('#toast');el.textContent=msg;el.classList.toggle('error',type==='error');el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),type==='error'?4200:2600);}
function navigate(view){activeView=view;$$('.view').forEach(x=>x.classList.toggle('active',x.id==='view-'+view));$$('.nav-btn').forEach(x=>x.classList.toggle('active',x.dataset.view===view));$('#pageTitle').textContent=titles[view][0];$('#pageSub').textContent=titles[view][1];if(view==='invoices')renderInvoices();if(view==='customers')renderCustomers();if(view==='items')renderProducts();if(view==='payments')renderPayments();if(view==='inventory')renderInventory();if(view==='purchases')renderPurchases();if(view==='suppliers')renderSuppliers();if(view==='expenses')renderExpenses();if(view==='quotations')renderQuotations();if(view==='warranties')renderWarranties();if(view==='recurring')renderRecurring();if(view==='reports')renderReports();if(view==='settings'){fillBusinessForm();renderUser();renderUsers();}if(view==='cashflow'){resetCashDates();renderCashFlow();}if(view==='staff')renderStaff();if(view==='assistant')renderAssistantInsights();}
function showModal(title,body,foot='',wide=false){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=body;$('#modalFoot').innerHTML=foot;$('#modal').classList.toggle('wide',wide);$('#modalBackdrop').classList.add('show');}
function closeModal(){stopCameraScanner();$('#modalBackdrop').classList.remove('show');}
function statCard(label,value,note,icon){return `<div class="stat"><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon}</span></div><div class="stat-value">${value}</div><div class="stat-note">${note}</div></div>`;}
function statusPill(s){return `<span class="status ${esc(s)}">${esc(s)}</span>`;}
function invoiceStats(list=state.invoices){const total=list.reduce((a,x)=>a+Number(x.total||0),0),paid=list.reduce((a,x)=>a+Number(x.paid||0),0),due=list.reduce((a,x)=>a+Number(x.balance||0),0);return{total,paid,due,count:list.length};}
function renderAll(){renderBrand();renderDashboard();renderInvoices();renderCustomers();renderProducts();renderPayments();renderSettingsState();renderInventory();renderPurchases();renderSuppliers();renderExpenses();renderQuotations();renderWarranties();renderRecurring();if(activeView==='reports')renderReports();if(activeView==='cashflow')renderCashFlow();if(activeView==='staff')renderStaff();if(activeView==='assistant')renderAssistantInsights();}
function renderDashboard(){
 const business=state.business||{},mStart=monthStart(),monthInvoices=state.invoices.filter(i=>i.invoice_date>=mStart),ms=invoiceStats(monthInvoices),collected=state.payments.filter(p=>p.payment_date>=mStart).reduce((a,p)=>a+Number(p.amount||0),0),all=invoiceStats();
 $('#welcomeTitle').textContent=business.name?`Good business, ${business.name}`:'Welcome to HisabFlow';$('#welcomeText').textContent=business.name?'Here is your latest business snapshot.':'Set up your business to start creating invoices and tracking payments.';const wb=$('#welcomeBtn');if(wb){wb.textContent=business.name?'＋ Create invoice':'Set up business →';wb.onclick=business.name?()=>openInvoiceForm():()=>navigate('settings');}
 $('#dashboardStats').innerHTML=statCard('SALES THIS MONTH',money(ms.total-(state.credit_notes||[]).filter(c=>c.note_date>=mStart).reduce((t,c)=>t+Number(c.total),0)),`${ms.count} invoice${ms.count===1?'':'s'} · net of credit notes`,'↗')+statCard('COLLECTED THIS MONTH',money(collected),'Payments received this month','₹')+statCard('TOTAL OUTSTANDING',money(all.due),'Across all unpaid invoices','◷')+statCard('TOTAL INVOICES',String(all.count),'All invoices created','▤');
 const recent=state.invoices.slice(0,6);$('#recentInvoices').innerHTML=recent.length?`<div class="table-wrap"><table><thead><tr><th>Invoice</th><th>Customer</th><th>Date</th><th class="right">Amount</th><th>Status</th></tr></thead><tbody>${recent.map(i=>`<tr><td><a class="click" onclick="viewInvoice(${i.id})">${esc(i.invoice_number)}</a></td><td>${esc(i.customer_name)}</td><td>${dateFmt(i.invoice_date)}</td><td class="right strong">${money(i.total)}</td><td>${statusPill(i.status)}</td></tr>`).join('')}</tbody></table></div>`:emptyState('No invoices yet','Your invoices will appear here.','Create your first invoice',"openInvoiceForm()");
 const dues=state.invoices.filter(i=>i.balance>0.009).sort((a,b)=>b.balance-a.balance).slice(0,5);$('#topDues').innerHTML=dues.length?`<div class="due-list">${dues.map(i=>`<div class="due-row"><div><b>${esc(i.customer_name)}</b><small>${esc(i.invoice_number)} · ${dateFmt(i.invoice_date)}</small></div><div style="text-align:right"><b>${money(i.balance)}</b><small><a class="click" onclick="openPaymentForm(${i.id})">Record payment</a></small></div></div>`).join('')}</div>`:'<div class="empty-inline">No outstanding payments. Nice work!</div>';
}
function emptyState(title,desc,button,fn){return `<div class="empty"><div class="empty-ico">◇</div><b>${title}</b><p>${desc}</p>${button?`<button class="btn primary" onclick="${fn}">${button}</button>`:''}</div>`;}
function renderInvoices(){const q=($('#invoiceSearch')?.value||'').toLowerCase(),status=$('#invoiceStatus')?.value||'All';let list=state.invoices.filter(i=>(i.invoice_number+' '+i.customer_name).toLowerCase().includes(q)&&(status==='All'||i.status===status));$('#invoiceTable').innerHTML=list.length?`<div class="table-wrap"><table><thead><tr><th>Invoice no.</th><th>Customer</th><th>Date</th><th class="right">Total</th><th class="right">Paid</th><th class="right">Balance</th><th>Status</th><th></th></tr></thead><tbody>${list.map(i=>`<tr><td class="strong">${esc(i.invoice_number)}</td><td>${esc(i.customer_name)}</td><td>${dateFmt(i.invoice_date)}</td><td class="right">${money(i.total)}</td><td class="right">${money(i.paid)}</td><td class="right strong">${money(i.balance)}</td><td>${statusPill(i.status)}</td><td><button class="btn small" onclick="viewInvoice(${i.id})">View / print</button></td></tr>`).join('')}</tbody></table></div>`:emptyState('No matching invoices','Create an invoice or change your search.','Create invoice','openInvoiceForm()');}
function renderCustomers(){const q=($('#customerSearch')?.value||'').toLowerCase();const list=state.customers.filter(c=>(c.name+' '+c.phone+' '+c.gstin).toLowerCase().includes(q));$('#customerCount').textContent=`${state.customers.length} saved`;$('#customerTable').innerHTML=list.length?`<div class="table-wrap"><table><thead><tr><th>Customer</th><th>Phone</th><th>State</th><th>GSTIN</th><th class="right">Outstanding</th><th></th></tr></thead><tbody>${list.map(c=>{const due=state.invoices.filter(i=>i.customer_id===c.id).reduce((a,i)=>a+i.balance,0);return `<tr><td class="strong">${esc(c.name)}</td><td>${esc(c.phone||'—')}</td><td>${esc(c.state||'—')}</td><td>${esc(c.gstin||'—')}</td><td class="right strong">${money(due)}</td><td><button class="btn small" onclick="openCustomerLedger(${c.id})">Ledger</button> <button class="btn small" onclick="openCustomerForm(${c.id})">Edit</button></td></tr>`}).join('')}</tbody></table></div>`:emptyState('No customers found','Add a customer to start billing.','Add customer','openCustomerForm()');}
function renderProducts(){const q=($('#productSearch')?.value||'').toLowerCase();const list=state.products.filter(p=>(p.name+' '+p.hsn+' '+(p.barcode||'')).toLowerCase().includes(q));$('#productCount').textContent=`${state.products.length} saved`;$('#productTable').innerHTML=list.length?`<div class="table-wrap"><table><thead><tr><th>Item / service</th><th>Barcode / SKU</th><th>HSN / SAC</th><th>Unit</th><th class="right">Sell rate</th><th class="right">Stock</th><th></th></tr></thead><tbody>${list.map(p=>`<tr><td class="strong">${esc(p.name)}${p.details?`<div class="item-details">${esc(p.details)}</div>`:''}</td><td class="barcode-cell">${esc(p.barcode||'—')}</td><td>${esc(p.hsn||'—')}</td><td>${esc(p.unit)}</td><td class="right">${money(p.rate)}</td><td class="right">${p.track_stock?num(p.stock_qty):'—'}</td><td><button class="btn small" onclick="printProductQR(${p.id})">QR</button> <button class="btn small" onclick="openProductForm(${p.id})">Edit</button></td></tr>`).join('')}</tbody></table></div>`:emptyState('No items found','Save products or services you bill regularly.','Add item','openProductForm()');}
function renderPayments(){const all=invoiceStats(),todayPaid=state.payments.filter(p=>p.payment_date===today()).reduce((a,p)=>a+Number(p.amount),0);$('#paymentStats').innerHTML=statCard('TOTAL COLLECTIONS',money(all.paid),'Across all recorded payments','₹')+statCard('OUTSTANDING',money(all.due),'Still to be collected','◷')+statCard('COLLECTED TODAY',money(todayPaid),'Payments recorded today','↗')+statCard('OPEN INVOICES',String(state.invoices.filter(i=>i.balance>0.009).length),'Invoices with a balance','▤');
 const due=state.invoices.filter(i=>i.balance>0.009);$('#outstandingTable').innerHTML=due.length?`<div class="table-wrap"><table><thead><tr><th>Invoice</th><th>Customer</th><th class="right">Due</th><th></th></tr></thead><tbody>${due.map(i=>`<tr><td><b>${esc(i.invoice_number)}</b><div class="tiny">${dateFmt(i.invoice_date)}</div></td><td>${esc(i.customer_name)}</td><td class="right strong">${money(i.balance)}</td><td><button class="btn small soft" onclick="openPaymentForm(${i.id})">＋ Payment</button> <button class="btn small" onclick="sendInvoiceReminder(${i.id})">WhatsApp</button></td></tr>`).join('')}</tbody></table></div>`:emptyState('No pending dues','All invoices are fully paid.');
 const pay=state.payments.slice(0,9);$('#paymentsTable').innerHTML=pay.length?`<div class="table-wrap"><table><thead><tr><th>Received from</th><th class="right">Amount</th><th>Date</th></tr></thead><tbody>${pay.map(p=>`<tr><td><b>${esc(p.customer_name)}</b><div class="tiny">${esc(p.method)} · ${esc(p.invoice_number)}</div></td><td class="right strong">${money(p.amount)}</td><td>${dateFmt(p.payment_date)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-inline" style="padding:18px">No payments recorded yet.</div>';
}
function renderSettingsState(){const b=state.business||{};if(b.name)$('#businessState').value=b.state||'';renderBrand();}
let pendingBusinessLogo='';
function logoImage(data=state.business?.logo_data,cls='bill-logo'){return data?`<img class="${cls}" src="${data}" alt="Business logo" style="max-width:110px;max-height:72px;object-fit:contain;display:block">`:'';}
function renderBrand(){const el=$('.brand-mark');if(!el)return;el.innerHTML=state.business?.logo_data?`<img class="brand-logo" src="${state.business.logo_data}" alt="Business logo">`:'HF';}
function previewBusinessLogo(input){const file=input.files?.[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)){toast('Choose a PNG, JPG or WebP image');input.value='';return;}if(file.size>650*1024){toast('Logo must be 650 KB or smaller');input.value='';return;}const reader=new FileReader();reader.onload=()=>{pendingBusinessLogo=String(reader.result||'');$('#businessLogoPreview').innerHTML=`${logoImage(pendingBusinessLogo)}<span>Logo ready to save. It will appear on printed bills.</span>`;};reader.readAsDataURL(file);}
function fillBusinessForm(){const f=$('#businessForm'),b=state.business||{};if(!f)return;for(const k of ['name','gstin','state','address','phone','email','invoice_prefix','bank_details','upi_id'])if(f.elements[k])f.elements[k].value=b[k]||'';pendingBusinessLogo='';$('#businessLogoPreview').innerHTML=b.logo_data?`${logoImage(b.logo_data)}<span>Current logo. Upload another image to replace it.</span>`:'No logo uploaded yet. Your business name will appear on bills.';if($('#businessLogoFile'))$('#businessLogoFile').value='';}
async function saveBusiness(){const f=$('#businessForm');if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));if(pendingBusinessLogo)d.logo_data=pendingBusinessLogo;try{await api('/api/business',{method:'POST',body:JSON.stringify(d)});await reload();fillBusinessForm();toast('Business profile saved. The logo will appear on new bills.');}catch(e){toast(e.message,'error');}}
$('#businessForm')?.addEventListener('submit',e=>{e.preventDefault();saveBusiness();});
function renderReports(){
 const from=$('#reportFrom')?.value||monthStart(),to=$('#reportTo')?.value||today(),invoices=state.invoices.filter(i=>i.invoice_date>=from&&i.invoice_date<=to),payments=state.payments.filter(p=>p.payment_date>=from&&p.payment_date<=to),expenses=state.expenses.filter(e=>e.expense_date>=from&&e.expense_date<=to),s=invoiceStats(invoices),received=payments.reduce((a,p)=>a+Number(p.amount),0),salesBase=invoices.reduce((a,i)=>a+Number(i.subtotal||0),0),cogs=invoices.reduce((a,i)=>a+Number(i.cost_of_goods||0),0),gross=salesBase-cogs,expenseTotal=expenses.reduce((a,e)=>a+Number(e.amount),0),net=gross-expenseTotal;const invoiceIds=new Set(invoices.map(i=>i.id)),periodItems=state.invoice_items.filter(x=>invoiceIds.has(x.invoice_id)),profitMap={};periodItems.forEach(x=>{const k=(x.product_id||'custom')+'|'+x.description;if(!profitMap[k])profitMap[k]={name:x.description,qty:0,sales:0,cost:0,profit:0};const z=profitMap[k];z.qty+=Number(x.qty);z.sales+=Number(x.taxable);z.cost+=Number(x.qty)*Number(x.cost_rate||0);z.profit+=Number(x.taxable)-Number(x.qty)*Number(x.cost_rate||0);});const productProfit=Object.values(profitMap).sort((a,b)=>b.profit-a.profit);const methodMap={};payments.forEach(p=>methodMap[p.method]=(methodMap[p.method]||0)+Number(p.amount));const due=state.invoices.filter(i=>i.balance>0.009).sort((a,b)=>b.balance-a.balance).slice(0,10);
 $('#reportContent').innerHTML=`<div class="grid report-cards">${statCard('INVOICED',money(s.total),`${s.count} invoices in selected period`,'▤')}${statCard('COLLECTED',money(received),`${payments.length} payment entries`,'₹')}${statCard('GROSS PROFIT EST.',money(gross),`Sales before tax ${money(salesBase)} less estimated item cost`,'↗')}${statCard('NET PROFIT EST.',money(net),`After recorded expenses of ${money(expenseTotal)}`,'₹')}${statCard('CUSTOMER DUES',money(s.due),'Outstanding on selected invoices','◷')}${statCard('EXPENSES',money(expenseTotal),`${expenses.length} expense records`,'▥')}</div><div class="notice" style="margin-bottom:15px">Profit is an operational estimate based on the purchase cost saved on each invoice line and expenses recorded here. It is not a substitute for statutory accounts, inventory valuation adjustments or tax/audit reporting.</div><div class="grid" style="grid-template-columns:1fr 1fr;gap:15px;margin-bottom:15px"><div class="panel"><div class="panel-head"><div><h3>Collections by payment mode</h3><p>Payments received in the selected period</p></div></div><div class="panel-body">${Object.keys(methodMap).length?Object.entries(methodMap).sort((a,b)=>b[1]-a[1]).map(([m,v])=>`<div class="due-row"><span>${esc(m)}</span><b>${money(v)}</b></div>`).join(''):'<div class="empty-inline">No collection entries in this period.</div>'}</div></div><div class="panel"><div class="panel-head"><div><h3>Product-wise profit estimate</h3><p>Sales less saved purchase cost for invoiced items</p></div></div><div class="table-wrap">${productProfit.length?`<table><thead><tr><th>Item</th><th class="right">Qty</th><th class="right">Sales</th><th class="right">Profit est.</th></tr></thead><tbody>${productProfit.slice(0,8).map(x=>`<tr><td>${esc(x.name)}</td><td class="right">${num(x.qty)}</td><td class="right">${money(x.sales)}</td><td class="right strong">${money(x.profit)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty-inline" style="padding:18px">No invoice line data in this period.</div>'}</div></div></div><div class="grid" style="grid-template-columns:minmax(0,1fr) minmax(280px,.9fr);gap:16px;align-items:start"><div class="panel"><div class="panel-head"><div><h3>Invoice activity</h3><p>${dateFmt(from)} — ${dateFmt(to)}</p></div><button class="btn small" onclick="exportInvoicesCSV(true)">Export CSV</button></div><div class="table-wrap">${invoices.length?`<table><thead><tr><th>Invoice</th><th>Customer</th><th>Total</th><th>Cost est.</th><th>Status</th></tr></thead><tbody>${invoices.map(i=>`<tr><td><a class="click" onclick="viewInvoice(${i.id})">${esc(i.invoice_number)}</a></td><td>${esc(i.customer_name)}</td><td class="strong">${money(i.total)}</td><td>${money(i.cost_of_goods||0)}</td><td>${statusPill(i.status)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty-inline" style="padding:20px">No invoices in this date range.</div>'}</div></div><div class="panel"><div class="panel-head"><div><h3>Top outstanding balances</h3><p>Across all dates</p></div></div><div class="panel-body">${due.length?`<div class="due-list">${due.map(i=>`<div class="due-row"><div><b>${esc(i.customer_name)}</b><small>${esc(i.invoice_number)}</small></div><b>${money(i.balance)}</b></div>`).join('')}</div>`:'<div class="empty-inline">No pending balances.</div>'}</div></div></div>`;
}
function resetReportDates(){$('#reportFrom').value=monthStart();$('#reportTo').value=today();renderReports();}
function openCustomerForm(id){const c=state.customers.find(x=>x.id===id)||{};const body=`<form id="customerForm"><input type="hidden" name="id" value="${c.id||''}"><div class="form-grid"><div class="field span2"><label>Customer / business name *</label><input name="name" required value="${esc(c.name||'')}" placeholder="Customer name"></div><div class="field"><label>Phone</label><input name="phone" value="${esc(c.phone||'')}"></div><div class="field"><label>Email</label><input name="email" type="email" value="${esc(c.email||'')}"></div><div class="field"><label>GSTIN (optional)</label><input name="gstin" maxlength="15" value="${esc(c.gstin||'')}"></div><div class="field"><label>State</label><select name="state"><option value="">Select state</option>${state.states.map(s=>`<option ${c.state===s?'selected':''}>${esc(s)}</option>`).join('')}</select></div><div class="field span2"><label>Billing address</label><textarea name="address">${esc(c.address||'')}</textarea></div></div></form>`;const foot=`${id?'<button class="btn danger" onclick="deleteCustomer('+id+')">Delete</button>':''}<span style="flex:1"></span><button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveCustomer()">Save customer</button>`;showModal(id?'Edit customer':'Add customer',body,foot);}
async function saveCustomer(){const f=$('#customerForm');if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));try{await api('/api/customers',{method:'POST',body:JSON.stringify(d)});await reload();closeModal();toast('Customer saved');}catch(e){toast(e.message,'error');}}
async function deleteCustomer(id){if(!confirm('Delete this customer? Customers used in invoices cannot be deleted.'))return;try{await api('/api/customers?id='+id,{method:'DELETE'});await reload();closeModal();toast('Customer deleted');}catch(e){toast(e.message,'error');}}
function openProductForm(id){const p=state.products.find(x=>x.id===id)||{};const body=`<form id="productForm"><input type="hidden" name="id" value="${p.id||''}"><div class="form-grid"><div class="field span2"><label>Item / service name *</label><input name="name" required value="${esc(p.name||'')}" placeholder="e.g. Repair service"></div><div class="field"><label>Barcode / SKU (optional)</label><input name="barcode" value="${esc(p.barcode||'')}" placeholder="Scan or enter product barcode"></div><div class="field"><label>HSN / SAC code</label><input name="hsn" value="${esc(p.hsn||'')}"></div><div class="field"><label>Unit</label><select name="unit">${['pcs','Nos','kg','ltr','meter','hour','service','box','set'].map(x=>`<option ${p.unit===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Selling rate (₹) *</label><input name="rate" type="number" min="0" step="0.01" required value="${p.rate??''}" placeholder="0.00"></div><div class="field"><label>Purchase / cost rate (₹)</label><input name="purchase_rate" type="number" min="0" step="0.01" value="${p.purchase_rate??0}"></div><div class="field"><label>GST rate (%)</label><input name="gst_rate" type="number" min="0" max="100" step="0.01" value="${p.gst_rate??0}"></div><div class="field"><label>Track inventory?</label><select name="track_stock"><option value="0" ${!p.track_stock?'selected':''}>No — service / non-stock</option><option value="1" ${p.track_stock?'selected':''}>Yes — track quantity</option></select></div><div class="field"><label>Opening stock / quantity</label><input name="stock_qty" type="number" min="0" step="0.001" value="${p.stock_qty??0}"></div><div class="field"><label>Low-stock alert at</label><input name="low_stock_level" type="number" min="0" step="0.001" value="${p.low_stock_level??0}"></div><div class="field span2"><label>Default item details (optional — copied onto new invoice lines)</label><textarea name="details" maxlength="1000" placeholder="e.g. Model: X200 · Colour: Black · 1-year manufacturer warranty">${esc(p.details||'')}</textarea></div></div></form>`;const foot=`${id?'<button class="btn danger" onclick="deleteProduct('+id+')">Delete</button>':''}<span style="flex:1"></span><button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveProduct()">Save item</button>`;showModal(id?'Edit item':'Add item',body,foot);}
async function saveProduct(){const f=$('#productForm');if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));d.track_stock=d.track_stock==='1';try{await api('/api/products',{method:'POST',body:JSON.stringify(d)});await reload();closeModal();toast('Item saved');}catch(e){toast(e.message,'error');}}
async function deleteProduct(id){if(!confirm('Delete this item? Items already used in invoices cannot be deleted.'))return;try{await api('/api/products?id='+id,{method:'DELETE'});await reload();closeModal();toast('Item deleted');}catch(e){toast(e.message,'error');}}
let invoiceRowCount=0;
function addInvoiceLine(item={}){const tbody=$('#invoiceLines');if(!tbody)return;const idx=invoiceRowCount++;const opts=state.products.map(p=>`<option value="${p.id}" ${item.product_id===p.id?'selected':''}>${esc(p.name)}</option>`).join('');const tr=document.createElement('tr');tr.dataset.idx=idx;tr.innerHTML=`<td><select class="line-product" aria-label="Saved item"><option value="">Custom item…</option>${opts}</select></td><td><input class="line-desc" value="${esc(item.description||'')}" placeholder="Description"><textarea class="line-details" rows="1" placeholder="Details: serial no. / IMEI, model, colour, size, batch, warranty…">${esc(item.details||'')}</textarea></td><td><input class="line-hsn" value="${esc(item.hsn||'')}" placeholder="HSN"></td><td><input class="line-qty" type="number" min="0.001" step="0.001" value="${item.qty??1}"></td><td><input class="line-unit" value="${esc(item.unit||'pcs')}" placeholder="pcs"></td><td><input class="line-rate" type="number" min="0" step="0.01" value="${item.rate??''}" placeholder="0"></td><td><input class="line-gst" type="number" min="0" max="100" step="0.01" value="${item.gst_rate??0}" aria-label="GST rate"></td><td class="right line-total">₹0.00</td><td><button type="button" class="btn small danger" onclick="this.closest('tr').remove();calcInvoice()">×</button></td>`;tbody.appendChild(tr);if(item.product_id){const p=state.products.find(x=>x.id===item.product_id);if(p){tr.querySelector('.line-product').value=p.id;if(!item.description)fillLineFromProduct(tr,p);}}tr.querySelectorAll('input,select').forEach(el=>el.addEventListener('input',()=>calcInvoice()));tr.querySelector('.line-product').addEventListener('change',e=>{const p=state.products.find(x=>x.id===Number(e.target.value));if(p)fillLineFromProduct(tr,p);calcInvoice();});calcInvoice();}
function fillLineFromProduct(tr,p){tr.querySelector('.line-desc').value=p.name;const det=tr.querySelector('.line-details');if(det&&!det.value.trim())det.value=p.details||'';tr.querySelector('.line-hsn').value=p.hsn||'';tr.querySelector('.line-rate').value=p.rate;tr.querySelector('.line-gst').value=Number(p.gst_rate||0);tr.querySelector('.line-unit').value=p.unit||'pcs';}
function calcInvoice(){let sub=0,tax=0;$$('#invoiceLines tr').forEach(tr=>{const q=Number(tr.querySelector('.line-qty').value||0),r=Number(tr.querySelector('.line-rate').value||0),g=Number(tr.querySelector('.line-gst').value==='custom'?0:tr.querySelector('.line-gst').value);const base=q*r,t=base*g/100;sub+=base;tax+=t;tr.querySelector('.line-total').textContent=money(base+t);});$('#invoiceSubtotal').textContent=money(sub);$('#invoiceTax').textContent=money(tax);$('#invoiceGrand').textContent=money(sub+tax);}
async function openInvoiceForm(id=null){if(!state.business?.name){toast('Please set up your business first');navigate('settings');return;}if(!state.customers.length){toast('Add a customer before creating an invoice');openCustomerForm();return;}let existing=null;if(id){try{existing=await api('/api/invoice?id='+id);}catch(e){toast(e.message,'error');return;}}invoiceRowCount=0;const body=`<form id="invoiceForm"><input type="hidden" name="id" value="${existing?.id||''}"><div class="form-grid three"><div class="field span2"><label>Customer *</label><select name="customer_id" required><option value="">Select customer</option>${state.customers.map(c=>`<option value="${c.id}" ${Number(existing?.customer_id)===c.id?'selected':''}>${esc(c.name)}${c.state?' · '+esc(c.state):''}</option>`).join('')}</select></div><div class="field"><label>Invoice date</label><input type="date" name="invoice_date" value="${existing?.invoice_date||today()}" required></div></div><div class="scanner-row"><div class="field"><label>Barcode / QR scan (USB scanner supported)</label><input id="invoiceScanInput" placeholder="Scan barcode, QR or type product code" onkeydown="if(event.key==='Enter'){event.preventDefault();scanProductCode(this.value)}"></div><button class="btn" type="button" onclick="startCameraScanner()">📷 Scan with camera</button></div><div class="divider"></div><div class="section-head" style="margin:0 0 10px"><div><h3 style="font-size:13px;margin:0">Invoice items</h3><p style="margin:3px 0 0">Enter price before GST.</p></div><button class="btn small" type="button" onclick="addInvoiceLine()">＋ Add line</button></div><div class="table-wrap"><table class="item-table"><thead><tr><th style="width:145px">Saved item</th><th>Description</th><th style="width:75px">HSN</th><th style="width:70px">Qty</th><th style="width:65px">Unit</th><th style="width:95px">Rate ₹</th><th style="width:76px">GST %</th><th class="right">Amount</th><th></th></tr></thead><tbody id="invoiceLines"></tbody></table></div><div class="invoice-total"><div class="total-row"><span>Taxable value</span><b id="invoiceSubtotal">₹0.00</b></div><div class="total-row"><span>GST (estimated)</span><b id="invoiceTax">₹0.00</b></div><div class="total-row grand"><span>Grand total</span><b id="invoiceGrand">₹0.00</b></div></div><div class="field" style="margin-top:18px"><label>Notes (optional)</label><textarea name="notes" placeholder="Payment terms, delivery note, thank you message…">${esc(existing?.notes||'')}</textarea></div></form><div class="notice" style="margin-top:13px">GST type (CGST/SGST or IGST) is determined from your business state and the customer's saved state. Review place of supply and tax treatment before issuing. Editing retains the existing invoice number and payment history; stock is adjusted automatically.</div>`;const foot=`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveInvoice()">${existing?'Save invoice changes':'Save invoice'}</button>`;showModal(existing?'Edit invoice '+existing.invoice_number:'Create new invoice',body,foot,true);if(existing?.items?.length)existing.items.forEach(it=>addInvoiceLine(it));else addInvoiceLine();$('#invoiceScanInput')?.focus();}
async function saveInvoice(){const f=$('#invoiceForm');if(!f.reportValidity())return;const items=$$('#invoiceLines tr').map(tr=>({product_id:tr.querySelector('.line-product').value||null,description:tr.querySelector('.line-desc').value,details:tr.querySelector('.line-details')?.value||'',hsn:tr.querySelector('.line-hsn').value,qty:tr.querySelector('.line-qty').value,rate:tr.querySelector('.line-rate').value,gst_rate:tr.querySelector('.line-gst').value,unit:tr.querySelector('.line-unit').value||'pcs'}));if(!items.length||items.some(x=>!x.description.trim())){toast('Add a description for every invoice line');return;}try{const d=Object.fromEntries(new FormData(f));d.customer_id=Number(d.customer_id);d.items=items;const editing=!!d.id;const result=await api(editing?'/api/invoices/update':'/api/invoices',{method:'POST',body:JSON.stringify(d)});await reload();closeModal();toast(editing?`Invoice ${result.invoice_number} updated`:`Invoice ${result.invoice_number} created`);viewInvoice(result.id);}catch(e){toast(e.message,'error');}}
async function viewInvoice(id){try{const inv=await api('/api/invoice?id='+id);const b=inv.business,c=inv.customer;const itemRows=inv.items.map(it=>`<tr><td>${esc(it.description)}${it.details?`<div class="item-details">${esc(it.details)}</div>`:''}${it.hsn?`<div class="tiny">HSN: ${esc(it.hsn)}</div>`:''}</td><td class="right">${num(it.qty)} ${esc(it.unit)}</td><td class="right">${money(it.rate)}</td><td class="right">${num(it.gst_rate)}%</td><td class="right">${money(it.line_total)}</td></tr>`).join('');const body=`<div style="display:flex;justify-content:space-between;gap:18px;align-items:flex-start"><div style="display:flex;gap:12px;align-items:flex-start">${logoImage(b.logo_data||state.business.logo_data)}<div><div style="font-size:18px;font-weight:850">${esc(b.name)}</div><div class="tiny">${esc(b.address||'')}${b.phone?' · '+esc(b.phone):''}</div><div class="tiny">${b.gstin?'GSTIN: '+esc(b.gstin):'Unregistered / GSTIN not entered'}</div></div></div><div style="text-align:right"><div style="font-size:16px;font-weight:850">${esc(inv.invoice_number)}</div><div class="tiny">Invoice date: ${dateFmt(inv.invoice_date)}</div><div style="margin-top:5px">${statusPill(inv.balance<=.009?'Paid':inv.paid>0?'Partial':'Unpaid')}</div></div></div><div class="divider"></div><div class="grid" style="grid-template-columns:1fr 1fr;gap:15px"><div><div class="tiny">BILL TO</div><b>${esc(c.name)}</b><div class="tiny">${esc(c.address||'')}</div><div class="tiny">${c.gstin?'GSTIN: '+esc(c.gstin):''}</div><div class="tiny">${esc(c.state||'')}</div></div><div><div class="tiny">PLACE OF SUPPLY</div><b>${esc(inv.place_of_supply||'—')}</b><div class="tiny">Tax treatment: ${esc(inv.supply_type)}</div></div></div><div class="divider"></div><div class="table-wrap"><table><thead><tr><th>Item</th><th class="right">Qty</th><th class="right">Rate</th><th class="right">GST</th><th class="right">Amount</th></tr></thead><tbody>${itemRows}</tbody></table></div><div class="invoice-total"><div class="total-row"><span>Taxable value</span><b>${money(inv.subtotal)}</b></div>${inv.igst>0?`<div class="total-row"><span>IGST</span><b>${money(inv.igst)}</b></div>`:`<div class="total-row"><span>CGST</span><b>${money(inv.cgst)}</b></div><div class="total-row"><span>SGST</span><b>${money(inv.sgst)}</b></div>`}<div class="total-row grand"><span>Total</span><b>${money(inv.total)}</b></div><div class="total-row"><span>Paid</span><b>${money(inv.paid)}</b></div><div class="total-row" style="color:#ad4b4b;font-weight:800"><span>Balance due</span><b>${money(inv.balance)}</b></div></div>${inv.notes?`<div class="divider"></div><div class="tiny"><b>Notes:</b> ${esc(inv.notes)}</div>`:''}${inv.payments.length?`<div class="divider"></div><b style="font-size:12px">Payment history</b><div class="tiny" style="margin-top:6px">${inv.payments.map(p=>`${dateFmt(p.payment_date)} · ${esc(p.method)} · ${money(p.amount)}${p.reference?' · '+esc(p.reference):''}`).join('<br>')}</div>`:''}<div class="notice" style="margin-top:17px">This print layout is a basic business invoice, not an IRN/e-invoice. Verify the mandatory fields and tax treatment for your transaction before issuing.</div>`;const foot=`${inv.balance>0.009?`<button class="btn soft" onclick="closeModal();openPaymentForm(${inv.id})">＋ Record payment</button>`:''}<span style="flex:1"></span><button class="btn" onclick="closeModal();openInvoiceForm(${inv.id})">Edit invoice</button><button class="btn" onclick="closeModal()">Close</button><button class="btn" onclick="shareInvoiceWhatsApp(${inv.id})">WhatsApp</button><button class="btn primary" onclick="printInvoice(${inv.id})">Print / Save PDF</button>`;showModal('Invoice details',body,foot,true);}catch(e){toast(e.message,'error');}}
async function printInvoice(id){const w=window.open('','_blank');if(!w){toast('Allow pop-ups to print this invoice');return;}try{const inv=await api('/api/invoice?id='+id);const b=inv.business,c=inv.customer;const rows=inv.items.map((it,n)=>`<tr><td>${n+1}</td><td>${esc(it.description)}<br><small>${it.hsn?'HSN/SAC: '+esc(it.hsn):''}</small></td><td class="r">${num(it.qty)} ${esc(it.unit)}</td><td class="r">${money(it.rate)}</td><td class="r">${num(it.gst_rate)}%</td><td class="r">${money(it.taxable)}</td><td class="r">${money(it.line_total-it.taxable)}</td><td class="r">${money(it.line_total)}</td></tr>`).join('');const taxRows=inv.igst>0?`<tr><td colspan="6">IGST</td><td class="r">${money(inv.igst)}</td><td></td></tr>`:`<tr><td colspan="6">CGST</td><td class="r">${money(inv.cgst)}</td><td></td></tr><tr><td colspan="6">SGST</td><td class="r">${money(inv.sgst)}</td><td></td></tr>`;const html=`<!doctype html><html><head><meta charset="utf-8"><title>${esc(inv.invoice_number)}</title><style>body{font:12px Arial,sans-serif;color:#182438;margin:30px}h1{font-size:21px;margin:0 0 5px}.muted{color:#66758c;font-size:10px}.top{display:flex;justify-content:space-between;gap:20px}.right{text-align:right}.rule{border-top:1px solid #cfd6df;margin:17px 0}.cols{display:flex;justify-content:space-between;gap:20px}.box{width:50%}table{border-collapse:collapse;width:100%;margin-top:18px}th{background:#f2f5f8;text-align:left;font-size:10px}td,th{border:1px solid #dce2e9;padding:8px 7px;vertical-align:top}.r{text-align:right;white-space:nowrap}.totals{margin:14px 0 0 auto;width:310px}.totals td{border:0;border-bottom:1px solid #e4e8ed}.grand{font-size:15px;font-weight:bold}.foot{margin-top:35px;display:flex;justify-content:space-between}.signature{text-align:right;margin-top:50px}.note{margin-top:18px;font-size:10px;color:#606e80}@media print{body{margin:14mm}button{display:none}}</style></head><body><div class="top"><div style="display:flex;gap:14px;align-items:flex-start">${logoImage(b.logo_data||state.business.logo_data)}<div><h1>${esc(b.name)}</h1><div>${esc(b.address||'')}</div><div>${b.phone?'Phone: '+esc(b.phone):''} ${b.email?' · '+esc(b.email):''}</div><div>${b.gstin?'GSTIN: '+esc(b.gstin):'GSTIN not provided'}</div></div></div><div class="right"><h1>${b.gstin?'TAX INVOICE':'INVOICE'}</h1><b>${esc(inv.invoice_number)}</b><div>Invoice date: ${dateFmt(inv.invoice_date)}</div><div>Place of supply: ${esc(inv.place_of_supply||'—')}</div></div></div><div class="rule"></div><div class="cols"><div class="box"><b>Bill To</b><br><b>${esc(c.name)}</b><br>${esc(c.address||'')}<br>${c.phone?'Phone: '+esc(c.phone):''}<br>${c.gstin?'GSTIN: '+esc(c.gstin):''}<br>${esc(c.state||'')}</div><div class="box right"><b>Supply type</b><br>${esc(inv.supply_type)}<br><b>Payment status</b><br>${inv.balance<=.009?'Paid':inv.paid>0?'Partially paid':'Unpaid'}</div></div><table><thead><tr><th>#</th><th>Description</th><th class="r">Qty</th><th class="r">Rate</th><th class="r">GST</th><th class="r">Taxable</th><th class="r">Tax</th><th class="r">Total</th></tr></thead><tbody>${rows}</tbody></table><table class="totals"><tr><td>Taxable value</td><td class="r">${money(inv.subtotal)}</td></tr>${taxRows}<tr class="grand"><td>Invoice total</td><td class="r">${money(inv.total)}</td></tr><tr><td>Amount paid</td><td class="r">${money(inv.paid)}</td></tr><tr><td><b>Balance due</b></td><td class="r"><b>${money(inv.balance)}</b></td></tr></table>${inv.notes?`<div class="note"><b>Notes:</b> ${esc(inv.notes)}</div>`:''}${b.bank_details||b.upi_id?`<div class="note"><b>Payment details:</b> ${esc(b.bank_details||'')} ${b.upi_id?' · UPI: '+esc(b.upi_id):''}</div>`:''}<div class="foot"><div class="note">Thank you for your business.</div><div class="signature">For <b>${esc(b.name)}</b><br><br>Authorised Signatory</div></div><div class="note">Generated using HisabFlow. Please verify applicable GST requirements before issuing.</div><script>window.onload=()=>setTimeout(()=>window.print(),300)<\/script></body></html>`;w.document.open();w.document.write(html);w.document.close();}catch(e){try{w.close();}catch(_){}toast(e.message,'error');}}
function openPaymentForm(invoiceId){const inv=state.invoices.find(i=>i.id===invoiceId);if(!inv)return;const body=`<form id="paymentForm"><input type="hidden" name="invoice_id" value="${inv.id}"><div class="notice">Invoice <b>${esc(inv.invoice_number)}</b> · ${esc(inv.customer_name)}<br>Outstanding balance: <b>${money(inv.balance)}</b></div><div class="form-grid" style="margin-top:14px"><div class="field"><label>Payment date *</label><input type="date" name="payment_date" value="${today()}" required></div><div class="field"><label>Amount received (₹) *</label><input type="number" name="amount" min="0.01" max="${inv.balance}" step="0.01" value="${inv.balance.toFixed(2)}" required></div><div class="field"><label>Payment method</label><select name="method"><option>Cash</option><option>UPI</option><option>Bank transfer</option><option>Card</option><option>Cheque</option><option>Other</option></select></div><div class="field"><label>Reference / transaction ID</label><input name="reference" placeholder="Optional"></div></div></form>`;showModal('Record payment',body,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="savePayment()">Save payment</button>`);}
async function savePayment(){const f=$('#paymentForm');if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));d.invoice_id=Number(d.invoice_id);try{await api('/api/payments',{method:'POST',body:JSON.stringify(d)});await reload();closeModal();toast('Payment recorded');if(activeView==='payments')renderPayments();}catch(e){toast(e.message,'error');}}
function csvCell(x){let v=String(x??'');if(typeof x==='string'&&/^[=+\-@\t\r]/.test(v))v="'"+v;return '"'+v.replace(/"/g,'""')+'"';}
function exportInvoicesCSV(periodOnly=false){const from=$('#reportFrom')?.value||'',to=$('#reportTo')?.value||'';const list=periodOnly?state.invoices.filter(i=>(!from||i.invoice_date>=from)&&(!to||i.invoice_date<=to)):state.invoices;const headers=['Invoice Number','Date','Customer','Total','Paid','Balance','Status'];const lines=[headers,...list.map(i=>[i.invoice_number,i.invoice_date,i.customer_name,i.total,i.paid,i.balance,i.status])];const csv=lines.map(row=>row.map(csvCell).join(',')).join('\r\n');downloadBlob(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),periodOnly&&from?`hisabflow-invoices-${from}-to-${to}.csv`:'hisabflow-invoices.csv');}
function downloadBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
async function downloadBackup(){try{const data=await api('/api/backup');downloadBlob(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),'hisabflow-backup-'+today()+'.json');toast('Backup downloaded');}catch(e){toast(e.message,'error');}}
async function restoreBackup(input){const file=input.files[0];if(!file)return;if(!confirm('Restore this backup? It will replace the records currently stored in HisabFlow.')){input.value='';return;}try{const data=JSON.parse(await file.text());await api('/api/restore',{method:'POST',body:JSON.stringify(data)});await reload();toast('Backup restored');}catch(e){toast('Restore failed: '+e.message,'error');}finally{input.value='';}}
// HisabFlow 2.0 modules: inventory, purchases, ledgers, expenses, quotations,
// warranty QR register, recurring billing and WhatsApp hand-off links.
const numById=id=>state.products.find(p=>p.id===Number(id));
let purchaseLineSeq=0;
function renderInventory(){
 const tracked=state.products.filter(p=>p.track_stock),low=tracked.filter(p=>Number(p.stock_qty)<=Number(p.low_stock_level)),value=tracked.reduce((a,p)=>a+Number(p.stock_qty||0)*Number(p.purchase_rate||0),0);
 $('#inventoryStats').innerHTML=statCard('TRACKED ITEMS',String(tracked.length),'Products with stock control','▦')+statCard('LOW-STOCK ALERTS',String(low.length),'At or below reorder level','!')+statCard('STOCK VALUE',money(value),'At recorded purchase cost','₹')+statCard('TOTAL CATALOGUE',String(state.products.length),'Products and services','◈');
 const q=($('#inventorySearch')?.value||'').toLowerCase();const list=tracked.filter(p=>(p.name+' '+p.hsn+' '+(p.barcode||'')).toLowerCase().includes(q));$('#lowStockCount').textContent=`${low.length} low-stock`;
 $('#inventoryTable').innerHTML=list.length?`<div class="table-wrap"><table><thead><tr><th>Item</th><th>Stock</th><th>Low-stock level</th><th class="right">Purchase rate</th><th class="right">Stock value</th><th>Status</th><th></th></tr></thead><tbody>${list.map(p=>{const isLow=Number(p.stock_qty)<=Number(p.low_stock_level);return `<tr><td class="strong">${esc(p.name)}<div class="tiny">${esc(p.unit)} · ${esc(p.hsn||'No HSN')}</div></td><td class="strong">${num(p.stock_qty)} ${esc(p.unit)}</td><td>${num(p.low_stock_level)} ${esc(p.unit)}</td><td class="right">${money(p.purchase_rate)}</td><td class="right strong">${money(Number(p.stock_qty)*Number(p.purchase_rate))}</td><td>${isLow?'<span class="status Unpaid">Low stock</span>':'<span class="status Paid">In stock</span>'}</td><td><button class="btn small" onclick="openStockAdjustment(${p.id})">Adjust</button> <button class="btn small" onclick="openProductForm(${p.id})">Edit</button></td></tr>`}).join('')}</tbody></table></div>`:emptyState('No tracked items','Edit an item and enable inventory tracking to see stock here.','Add item','openProductForm()');
}
function openStockAdjustment(productId){const opts=state.products.filter(p=>p.track_stock).map(p=>`<option value="${p.id}" ${p.id===productId?'selected':''}>${esc(p.name)} · ${num(p.stock_qty)} ${esc(p.unit)} available</option>`).join('');if(!opts){toast('Enable stock tracking on at least one item first');return;}const body=`<form id="stockAdjustForm"><div class="form-grid"><div class="field span2"><label>Product *</label><select name="product_id" required>${opts}</select></div><div class="field"><label>Quantity change *</label><input name="quantity" type="number" step="0.001" required placeholder="Use + to add, − to reduce"></div><div class="field"><label>Date</label><input name="movement_date" type="date" value="${today()}"></div><div class="field span2"><label>Reason</label><input name="reason" value="Physical stock count / correction"></div></div><div class="notice" style="margin-top:12px">Use positive quantity to add stock and negative quantity to reduce stock. Stock cannot go below zero.</div></form>`;showModal('Adjust stock',body,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveStockAdjustment()">Save adjustment</button>`);}
async function saveStockAdjustment(){const f=$('#stockAdjustForm');if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));d.product_id=Number(d.product_id);d.quantity=Number(d.quantity);try{await api('/api/stock-adjustments',{method:'POST',body:JSON.stringify(d)});await reload();closeModal();toast('Stock updated');}catch(e){toast(e.message,'error');}}

function supplierDue(sid){return state.purchases.filter(p=>p.supplier_id===sid).reduce((a,p)=>a+Number(p.balance||0),0);}
function renderSuppliers(){const q=($('#supplierSearch')?.value||'').toLowerCase(),list=state.suppliers.filter(s=>(s.name+' '+s.phone+' '+s.gstin).toLowerCase().includes(q));$('#supplierCount').textContent=`${state.suppliers.length} saved`;
 $('#supplierTable').innerHTML=list.length?`<div class="table-wrap"><table><thead><tr><th>Supplier</th><th>Phone</th><th>GSTIN</th><th class="right">Payable</th><th></th></tr></thead><tbody>${list.map(s=>`<tr><td class="strong">${esc(s.name)}<div class="tiny">${esc(s.state||'')}</div></td><td>${esc(s.phone||'—')}</td><td>${esc(s.gstin||'—')}</td><td class="right strong">${money(supplierDue(s.id))}</td><td><button class="btn small" onclick="openSupplierLedger(${s.id})">Ledger</button> <button class="btn small" onclick="openSupplierForm(${s.id})">Edit</button></td></tr>`).join('')}</tbody></table></div>`:emptyState('No suppliers yet','Add the suppliers you buy stock or services from.','Add supplier','openSupplierForm()');}
function openSupplierForm(id){const s=state.suppliers.find(x=>x.id===id)||{};const body=`<form id="supplierForm"><input type="hidden" name="id" value="${s.id||''}"><div class="form-grid"><div class="field span2"><label>Supplier / business name *</label><input name="name" required value="${esc(s.name||'')}"></div><div class="field"><label>Phone</label><input name="phone" value="${esc(s.phone||'')}"></div><div class="field"><label>Email</label><input name="email" type="email" value="${esc(s.email||'')}"></div><div class="field"><label>GSTIN</label><input name="gstin" maxlength="15" value="${esc(s.gstin||'')}"></div><div class="field"><label>State</label><select name="state"><option value="">Select state</option>${state.states.map(x=>`<option ${s.state===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="field span2"><label>Address</label><textarea name="address">${esc(s.address||'')}</textarea></div></div></form>`;showModal(id?'Edit supplier':'Add supplier',body,`${id?`<button class="btn danger" onclick="deleteSupplier(${id})">Delete</button>`:''}<span style="flex:1"></span><button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveSupplier()">Save supplier</button>`);}
async function saveSupplier(){const f=$('#supplierForm');if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));try{await api('/api/suppliers',{method:'POST',body:JSON.stringify(d)});await reload();closeModal();toast('Supplier saved');}catch(e){toast(e.message,'error');}}
async function deleteSupplier(id){if(!confirm('Delete this supplier? Suppliers used by purchases cannot be deleted.'))return;try{await api('/api/suppliers?id='+id,{method:'DELETE'});await reload();closeModal();toast('Supplier deleted');}catch(e){toast(e.message,'error');}}
function openSupplierLedger(id){const s=state.suppliers.find(x=>x.id===id);if(!s)return;const list=state.purchases.filter(p=>p.supplier_id===id);const body=`<div class="grid stats" style="grid-template-columns:repeat(3,1fr)">${statCard('PURCHASES',money(list.reduce((a,p)=>a+p.total,0)),'Total supplier bills','⇩')}${statCard('PAID',money(list.reduce((a,p)=>a+p.paid,0)),'Supplier payments','₹')}${statCard('PAYABLE',money(supplierDue(id)),'Remaining balance','◷')}</div><div class="panel"><div class="panel-head"><b>${esc(s.name)} · Supplier ledger</b><span class="tiny">${esc(s.phone||'')}</span></div><div class="table-wrap"><table><thead><tr><th>Purchase</th><th>Date</th><th class="right">Bill</th><th class="right">Paid</th><th class="right">Balance</th></tr></thead><tbody>${list.map(p=>`<tr><td>${esc(p.purchase_number)}</td><td>${dateFmt(p.purchase_date)}</td><td class="right">${money(p.total)}</td><td class="right">${money(p.paid)}</td><td class="right strong">${money(p.balance)}</td></tr>`).join('')||'<tr><td colspan="5">No purchases yet.</td></tr>'}</tbody></table></div></div>`;showModal('Supplier ledger',body,`<button class="btn" onclick="closeModal()">Close</button>`,true);}

function renderPurchases(){const total=state.purchases.reduce((a,p)=>a+Number(p.total),0),paid=state.purchases.reduce((a,p)=>a+Number(p.paid),0),due=state.purchases.reduce((a,p)=>a+Number(p.balance),0);$('#purchaseStats').innerHTML=statCard('PURCHASE VALUE',money(total),'Supplier bills recorded','⇩')+statCard('PAID TO SUPPLIERS',money(paid),'Payments made','₹')+statCard('SUPPLIER PAYABLE',money(due),'Remaining supplier balances','◷')+statCard('PURCHASE BILLS',String(state.purchases.length),'Recorded bills','▤');$('#purchaseTable').innerHTML=state.purchases.length?`<div class="table-wrap"><table><thead><tr><th>Purchase</th><th>Supplier</th><th>Date</th><th class="right">Total</th><th class="right">Paid</th><th class="right">Balance</th><th></th></tr></thead><tbody>${state.purchases.map(p=>`<tr><td class="strong">${esc(p.purchase_number)}</td><td>${esc(p.supplier_name)}</td><td>${dateFmt(p.purchase_date)}</td><td class="right">${money(p.total)}</td><td class="right">${money(p.paid)}</td><td class="right strong">${money(p.balance)}</td><td>${p.balance>.009?`<button class="btn small" onclick="openSupplierPayment(${p.id})">Pay</button>`:''} <button class="btn small" onclick="viewPurchase(${p.id})">View / print</button>${!p.paid&&!p.returned?` <button class="btn small" onclick="openPurchaseForm(${p.id})">Edit</button>`:''} <button class="btn small" onclick="openPurchaseReturn(${p.id})">Debit note</button></td></tr>`).join('')}</tbody></table></div>`:emptyState('No purchases recorded','Record a supplier purchase to receive stock and track payables.','Record purchase','openPurchaseForm()');}
function addPurchaseLine(item={}){const tbody=$('#purchaseLines');if(!tbody)return;const idx=purchaseLineSeq++;const opts=state.products.map(p=>`<option value="${p.id}" ${item.product_id===p.id?'selected':''}>${esc(p.name)}</option>`).join('');const tr=document.createElement('tr');tr.innerHTML=`<td><select class="pur-product"><option value="">Choose item…</option>${opts}</select></td><td><input class="pur-desc" value="${esc(item.description||'')}" placeholder="Description"></td><td><input class="pur-qty" type="number" min="0.001" step="0.001" value="${item.qty??1}"></td><td><input class="pur-rate" type="number" min="0" step="0.01" value="${item.rate??''}" placeholder="Rate"></td><td><input class="pur-gst" type="number" min="0" max="100" step="0.01" value="${item.gst_rate??0}"></td><td><button type="button" class="btn small danger" onclick="this.closest('tr').remove()">×</button></td>`;tbody.appendChild(tr);const sel=tr.querySelector('.pur-product');sel.addEventListener('change',()=>{const p=numById(sel.value);if(p){tr.querySelector('.pur-desc').value=p.name;tr.querySelector('.pur-rate').value=p.purchase_rate||p.rate;tr.querySelector('.pur-gst').value=p.gst_rate;}});}
async function openPurchaseForm(id=null){if(!state.suppliers.length){toast('Add a supplier first');openSupplierForm();return;}if(!state.products.length){toast('Add products first');openProductForm();return;}let existing=null;if(id){try{existing=await api('/api/purchase?id='+id);if(existing.paid>0||existing.returned>0){toast('A purchase with payments or returns cannot be edited safely.');return;}}catch(e){toast(e.message,'error');return;}}purchaseLineSeq=0;const body=`<form id="purchaseForm"><input type="hidden" name="id" value="${existing?.id||''}"><div class="form-grid"><div class="field"><label>Supplier *</label><select name="supplier_id" required><option value="">Select supplier</option>${state.suppliers.map(s=>`<option value="${s.id}" ${Number(existing?.supplier_id)===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div><div class="field"><label>Purchase date</label><input type="date" name="purchase_date" value="${existing?.purchase_date||today()}"></div><div class="field"><label>Paid now (₹)</label><input type="number" min="0" step="0.01" name="paid_amount" value="0" ${existing?'disabled':''}></div><div class="field"><label>Payment method</label><select name="method" ${existing?'disabled':''}><option>Cash</option><option>UPI</option><option>Bank transfer</option><option>Cheque</option><option>Other</option></select></div><div class="field span2"><label>Reference</label><input name="reference" placeholder="Transaction / supplier bill reference" ${existing?'disabled':''}></div></div><div class="scanner-row"><div class="field"><label>Barcode / QR scan (USB scanner supported)</label><input id="purchaseScanInput" placeholder="Scan or type product barcode" onkeydown="if(event.key==='Enter'){event.preventDefault();scanProductCode(this.value,'purchase')}"></div><button class="btn" type="button" onclick="startCameraScanner('purchase')">📷 Scan with camera</button></div><div class="divider"></div><div class="section-head"><div><h3>Purchase items</h3><p>Received quantities are added to stock for inventory-tracked products.</p></div><button class="btn small" type="button" onclick="addPurchaseLine()">＋ Add line</button></div><div class="table-wrap"><table class="item-table"><thead><tr><th>Saved item</th><th>Description</th><th>Qty</th><th>Purchase rate ₹</th><th>GST %</th><th></th></tr></thead><tbody id="purchaseLines"></tbody></table></div><div class="field" style="margin-top:12px"><label>Notes</label><textarea name="notes">${esc(existing?.notes||'')}</textarea></div></form>${existing?'<div class="notice" style="margin-top:12px">This purchase bill has no payments or returns, so it can be edited. Stock will be adjusted by the difference in quantities.</div>':''}`;showModal(existing?'Edit purchase '+existing.purchase_number:'Record purchase',body,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="savePurchase()">${existing?'Save changes':'Save purchase'}</button>`,true);if(existing?.items?.length)existing.items.forEach(it=>addPurchaseLine(it));else addPurchaseLine();}
async function savePurchase(){const f=$('#purchaseForm');if(!f.reportValidity())return;const items=$$('#purchaseLines tr').map(tr=>({product_id:tr.querySelector('.pur-product').value||null,description:tr.querySelector('.pur-desc').value,qty:tr.querySelector('.pur-qty').value,rate:tr.querySelector('.pur-rate').value,gst_rate:tr.querySelector('.pur-gst').value}));if(!items.length||items.some(x=>!x.description.trim())){toast('Complete each purchase line');return;}const d=Object.fromEntries(new FormData(f));d.supplier_id=Number(d.supplier_id);d.items=items;const editing=!!d.id;try{const r=await api(editing?'/api/purchases/update':'/api/purchases',{method:'POST',body:JSON.stringify(d)});await reload();closeModal();toast(editing?`Purchase ${r.purchase_number} updated`:`Purchase ${r.purchase_number} saved; stock updated`);}catch(e){toast(e.message,'error');}}
async function viewPurchase(id){try{const p=await api('/api/purchase?id='+id);const b=state.business||{};const body=`<div style="display:flex;gap:12px;align-items:center">${logoImage(b.logo_data)}<div><b>${esc(b.name||'Business')}</b><div class="tiny">${esc(b.address||'')} ${esc(b.phone||'')}</div></div></div><div class="divider"></div><div><b>${esc(p.purchase_number)}</b> · ${dateFmt(p.purchase_date)}<p>Supplier: ${esc(p.supplier.name||'')}</p></div><div class="table-wrap"><table><thead><tr><th>Item</th><th>Qty</th><th>Rate</th><th>Total</th></tr></thead><tbody>${p.items.map(x=>`<tr><td>${esc(x.description)}${x.details?`<div class="item-details">${esc(x.details)}</div>`:''}</td><td>${num(x.qty)}</td><td>${money(x.rate)}</td><td>${money(x.line_total)}</td></tr>`).join('')}</tbody></table></div><div class="invoice-total"><div class="total-row grand"><span>Total</span><b>${money(p.total)}</b></div></div>${p.notes?`<div class="tiny">Notes: ${esc(p.notes)}</div>`:''}`;showModal('Purchase bill details',body,`${!p.paid&&!p.returned?`<button class="btn" onclick="closeModal();openPurchaseForm(${p.id})">Edit bill</button>`:''}<button class="btn" onclick="printPurchase(${p.id})">Print / PDF</button><button class="btn" onclick="closeModal()">Close</button>`);}catch(e){toast(e.message,'error');}}
async function printPurchase(id){const w=window.open('','_blank');if(!w){toast('Allow pop-ups to print');return;}try{const p=await api('/api/purchase?id='+id),b=state.business||{};w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>${esc(p.purchase_number)}</title><style>body{font:13px Arial;margin:28px;color:#17243a}.top{display:flex;gap:14px;align-items:center}img{max-width:110px;max-height:70px}table{width:100%;border-collapse:collapse;margin-top:20px}td,th{border:1px solid #dce2e9;padding:8px;text-align:left}th{background:#f2f5f8}.r{text-align:right}.muted{color:#65748a;font-size:11px}</style></head><body><div class="top">${logoImage(b.logo_data)}<div><h1>${esc(b.name||'Business')}</h1><div class="muted">${esc(b.address||'')} ${esc(b.phone||'')}</div></div></div><hr><h2>Purchase bill</h2><b>${esc(p.purchase_number)}</b> · ${dateFmt(p.purchase_date)}<p>Supplier: ${esc(p.supplier.name||'')}</p><table><tr><th>Item</th><th>Qty</th><th>Rate</th><th>Total</th></tr>${p.items.map(x=>`<tr><td>${esc(x.description)}${x.details?`<div class="item-details">${esc(x.details)}</div>`:''}</td><td>${num(x.qty)}</td><td>${money(x.rate)}</td><td>${money(x.line_total)}</td></tr>`).join('')}</table><h2 class="r">Total: ${money(p.total)}</h2><p>${esc(p.notes||'')}</p><script>window.onload=()=>setTimeout(()=>window.print(),250)<\/script></body></html>`);w.document.close();}catch(e){try{w.close()}catch(_){}toast(e.message,'error');}}
function openSupplierPayment(id){const p=state.purchases.find(x=>x.id===id);if(!p)return;const body=`<form id="supplierPaymentForm"><input type="hidden" name="purchase_id" value="${id}"><div class="notice">${esc(p.purchase_number)} · ${esc(p.supplier_name)}<br>Outstanding: <b>${money(p.balance)}</b></div><div class="form-grid" style="margin-top:13px"><div class="field"><label>Payment date</label><input type="date" name="payment_date" value="${today()}"></div><div class="field"><label>Amount (₹)</label><input type="number" name="amount" min="0.01" max="${p.balance}" step="0.01" value="${Number(p.balance).toFixed(2)}" required></div><div class="field"><label>Method</label><select name="method"><option>Cash</option><option>UPI</option><option>Bank transfer</option><option>Cheque</option></select></div><div class="field"><label>Reference</label><input name="reference"></div></div></form>`;showModal('Pay supplier',body,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveSupplierPayment()">Save payment</button>`);}
async function saveSupplierPayment(){const f=$('#supplierPaymentForm');if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));d.purchase_id=Number(d.purchase_id);try{await api('/api/supplier-payments',{method:'POST',body:JSON.stringify(d)});await reload();closeModal();toast('Supplier payment recorded');}catch(e){toast(e.message,'error');}}
async function openPurchaseReturn(purchaseId){if(!purchaseId){toast('Open a purchase bill and choose Return');return;}try{const p=await api('/api/purchase?id='+purchaseId);const rows=p.items.filter(x=>x.product_id);if(!rows.length){toast('This purchase has no linked catalogue items to return');return;}const body=`<form id="purchaseReturnForm"><input type="hidden" name="purchase_id" value="${p.id}"><div class="notice">Return against ${esc(p.purchase_number)} · ${esc(p.supplier.name||'')}</div><div class="form-grid" style="margin-top:12px"><div class="field span2"><label>Item to return *</label><select name="product_id" id="returnProduct" required>${rows.map(x=>`<option value="${x.product_id}" data-rate="${x.rate}" data-gst="${x.gst_rate||0}" data-description="${esc(x.description)}">${esc(x.description)} · Purchased ${num(x.qty)}</option>`).join('')}</select></div><div class="field"><label>Quantity returned *</label><input name="qty" type="number" min="0.001" step="0.001" required value="1"></div><div class="field"><label>Rate (₹)</label><input name="rate" id="returnRate" type="number" min="0" step="0.01" required value="${rows[0].rate}"></div><div class="field"><label>GST rate (%)</label><input name="gst_rate" id="returnGST" type="number" min="0" max="100" step="0.01" value="${rows[0].gst_rate||0}"></div><div class="field span2"><label>Reason</label><input name="notes" placeholder="Damaged / excess / wrong item"></div></div></form>`;showModal('Purchase return',body,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="savePurchaseReturn()">Save return</button>`);$('#returnProduct').addEventListener('change',e=>{$('#returnRate').value=e.target.selectedOptions[0].dataset.rate||0;$('#returnGST').value=e.target.selectedOptions[0].dataset.gst||0;});}catch(e){toast(e.message,'error');}}
async function savePurchaseReturn(){const f=$('#purchaseReturnForm');if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));d.purchase_id=Number(d.purchase_id);d.items=[{product_id:Number(d.product_id),qty:d.qty,rate:d.rate,gst_rate:d.gst_rate}];try{const r=await api('/api/purchase-returns',{method:'POST',body:JSON.stringify(d)});await reload();closeModal();toast(`Return ${r.return_number} saved`);}catch(e){toast(e.message,'error');}}

function renderExpenses(){const total=state.expenses.reduce((a,x)=>a+Number(x.amount),0),todayTotal=state.expenses.filter(x=>x.expense_date===today()).reduce((a,x)=>a+Number(x.amount),0),thisMonth=state.expenses.filter(x=>x.expense_date>=monthStart()).reduce((a,x)=>a+Number(x.amount),0);$('#expenseStats').innerHTML=statCard('TOTAL EXPENSES',money(total),'All recorded expenses','₹')+statCard('THIS MONTH',money(thisMonth),'Current month','▥')+statCard('TODAY',money(todayTotal),'Expenses dated today','◷')+statCard('ENTRIES',String(state.expenses.length),'Expense records','▤');$('#expenseTable').innerHTML=state.expenses.length?`<div class="table-wrap"><table><thead><tr><th>Date</th><th>Category</th><th>Description</th><th>Method</th><th class="right">Amount</th><th></th></tr></thead><tbody>${state.expenses.map(e=>`<tr><td>${dateFmt(e.expense_date)}</td><td>${esc(e.category)}</td><td class="strong">${esc(e.description)}</td><td>${esc(e.method)}</td><td class="right strong">${money(e.amount)}</td><td><button class="btn small" onclick="openExpenseForm(${e.id})">Edit</button> <button class="btn small danger" onclick="deleteExpense(${e.id})">Delete</button></td></tr>`).join('')}</tbody></table></div>`:emptyState('No expenses yet','Record rent, wages, transport, electricity and other business costs.','Add expense','openExpenseForm()');}
function openExpenseForm(id=null){const e=state.expenses.find(x=>x.id===id)||{};const cats=['Rent','Salary / wages','Electricity','Transport / fuel','Repairs','Telephone / internet','Marketing','Office supplies','Bank charges','Other'];const body=`<form id="expenseForm"><input type="hidden" name="id" value="${e.id||''}"><div class="form-grid"><div class="field"><label>Date</label><input type="date" name="expense_date" value="${e.expense_date||today()}"></div><div class="field"><label>Category</label><select name="category">${cats.map(x=>`<option ${e.category===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field span2"><label>Description *</label><input id="expenseDescription" name="description" required value="${esc(e.description||'')}" placeholder="What was this expense for?" oninput="suggestExpenseCategory(this.value)"></div><div class="field"><label>Amount (₹) *</label><input name="amount" type="number" min="0.01" step="0.01" value="${e.amount??''}" required></div><div class="field"><label>Payment method</label><select name="method">${['Cash','UPI','Bank transfer','Card','Cheque','Other'].map(x=>`<option ${e.method===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field span2"><label>Reference</label><input name="reference" value="${esc(e.reference||'')}" placeholder="Optional transaction ID / bill number"></div></div></form>`;showModal(e.id?'Edit expense':'Add expense',body,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveExpense()">Save expense</button>`);}
async function saveExpense(){const f=$('#expenseForm');if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));try{await api('/api/expenses',{method:'POST',body:JSON.stringify(d)});await reload();closeModal();toast(d.id?'Expense updated':'Expense saved');}catch(e){toast(e.message,'error');}}
async function deleteExpense(id){if(!confirm('Delete this expense entry?'))return;try{await api('/api/expenses?id='+id,{method:'DELETE'});await reload();toast('Expense deleted');}catch(e){toast(e.message,'error');}}

let quoteLineSeq=0;
function addQuoteLine(item={}){const tb=$('#quoteLines');if(!tb)return;quoteLineSeq++;const opts=state.products.map(p=>`<option value="${p.id}" ${item.product_id===p.id?'selected':''}>${esc(p.name)}</option>`).join('');const tr=document.createElement('tr');tr.innerHTML=`<td><select class="ql-product"><option value="">Custom</option>${opts}</select></td><td><input class="ql-desc" value="${esc(item.description||'')}" placeholder="Description"><textarea class="ql-details line-details" rows="1" placeholder="Details: serial no. / IMEI, model, colour, size, batch, warranty…">${esc(item.details||'')}</textarea></td><td><input class="ql-qty" type="number" step="0.001" min="0.001" value="${item.qty??1}"></td><td><input class="ql-rate" type="number" step="0.01" min="0" value="${item.rate??''}"></td><td><input class="ql-gst" type="number" min="0" max="100" step="0.01" value="${item.gst_rate??0}"></td><td><button type="button" class="btn small danger" onclick="this.closest('tr').remove()">×</button></td>`;tb.appendChild(tr);tr.querySelector('.ql-product').addEventListener('change',e=>{const p=numById(e.target.value);if(p){tr.querySelector('.ql-desc').value=p.name;if(!tr.querySelector('.ql-details').value.trim())tr.querySelector('.ql-details').value=p.details||'';tr.querySelector('.ql-rate').value=p.rate;tr.querySelector('.ql-gst').value=p.gst_rate;}});}
async function openQuotationForm(id=null){if(!state.customers.length){toast('Add a customer first');openCustomerForm();return;}let existing=null;if(id){try{existing=await api('/api/quotation?id='+id);if(existing.converted_invoice_id){toast('A converted quotation cannot be edited');return;}}catch(e){toast(e.message,'error');return;}}quoteLineSeq=0;const body=`<form id="quoteForm"><input type="hidden" name="id" value="${existing?.id||''}"><div class="form-grid"><div class="field"><label>Customer *</label><select name="customer_id" required><option value="">Select customer</option>${state.customers.map(c=>`<option value="${c.id}" ${Number(existing?.customer_id)===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Quotation date</label><input type="date" name="quote_date" value="${existing?.quote_date||today()}"></div></div><div class="divider"></div><div class="section-head"><div><h3>Quote items</h3><p>Quotes do not deduct stock until converted to an invoice.</p></div><button type="button" class="btn small" onclick="addQuoteLine()">＋ Add line</button></div><div class="table-wrap"><table class="item-table"><thead><tr><th>Item</th><th>Description</th><th>Qty</th><th>Rate ₹</th><th>GST %</th><th></th></tr></thead><tbody id="quoteLines"></tbody></table></div><div class="field" style="margin-top:12px"><label>Notes / validity terms</label><textarea name="notes" placeholder="Quote valid for 15 days…">${esc(existing?.notes||'')}</textarea></div></form>`;showModal(existing?'Edit quotation '+existing.quote_number:'Create quotation',body,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveQuotation()">${existing?'Save changes':'Save quotation'}</button>`,true);if(existing?.items?.length)existing.items.forEach(it=>addQuoteLine(it));else addQuoteLine();}
async function saveQuotation(){const f=$('#quoteForm');if(!f.reportValidity())return;const items=$$('#quoteLines tr').map(tr=>({product_id:tr.querySelector('.ql-product').value||null,description:tr.querySelector('.ql-desc').value,details:tr.querySelector('.ql-details')?.value||'',qty:tr.querySelector('.ql-qty').value,rate:tr.querySelector('.ql-rate').value,gst_rate:tr.querySelector('.ql-gst').value}));if(!items.length||items.some(x=>!x.description.trim())){toast('Complete each quotation line');return;}const d=Object.fromEntries(new FormData(f));d.customer_id=Number(d.customer_id);d.items=items;const editing=!!d.id;try{await api(editing?'/api/quotations/update':'/api/quotations',{method:'POST',body:JSON.stringify(d)});await reload();closeModal();toast(editing?'Quotation updated':'Quotation saved');}catch(e){toast(e.message,'error');}}
function renderQuotations(){$('#quotationTable').innerHTML=state.quotations.length?`<div class="table-wrap"><table><thead><tr><th>Quote</th><th>Customer</th><th>Date</th><th class="right">Total</th><th>Status</th><th></th></tr></thead><tbody>${state.quotations.map(q=>`<tr><td class="strong">${esc(q.quote_number)}</td><td>${esc(q.customer_name)}</td><td>${dateFmt(q.quote_date)}</td><td class="right">${money(q.total)}</td><td>${statusPill(q.status)}</td><td><button class="btn small" onclick="viewQuotation(${q.id})">View</button> ${q.status!=='Converted'?`<button class="btn small" onclick="setQuoteStatus(${q.id},'Accepted')">Accept</button> <button class="btn small" onclick="setQuoteStatus(${q.id},'Rejected')">Reject</button> <button class="btn small" onclick="convertQuotation(${q.id})">Convert</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:emptyState('No quotations yet','Prepare a quote before confirming a customer order.','New quotation','openQuotationForm()');}
async function setQuoteStatus(id,status){try{await api('/api/quotations/status',{method:'POST',body:JSON.stringify({id,status})});await reload();toast('Quotation updated');}catch(e){toast(e.message,'error');}}
async function convertQuotation(id){if(!confirm('Convert this quotation into an invoice? This will also deduct tracked inventory stock.'))return;try{const r=await api('/api/quotations/convert',{method:'POST',body:JSON.stringify({id})});await reload();toast(`Created invoice ${r.invoice_number}`);viewInvoice(r.invoice_id);}catch(e){toast(e.message,'error');}}
async function viewQuotation(id){try{const q=await api('/api/quotation?id='+id);const body=`<div style="display:flex;gap:12px;align-items:center">${logoImage(state.business.logo_data)}<div><b>${esc(state.business.name||'Business')}</b><div class="tiny">${esc(state.business.address||'')}</div></div></div><div style="display:flex;justify-content:space-between;margin-top:14px"><div><b>${esc(q.customer.name)}</b><div class="tiny">${dateFmt(q.quote_date)}</div></div><h3>${esc(q.quote_number)}</h3></div><div class="table-wrap"><table><thead><tr><th>Item</th><th>Qty</th><th>Rate</th><th>Total</th></tr></thead><tbody>${q.items.map(x=>`<tr><td>${esc(x.description)}${x.details?`<div class="item-details">${esc(x.details)}</div>`:''}</td><td>${num(x.qty)}</td><td>${money(x.rate)}</td><td>${money(x.line_total)}</td></tr>`).join('')}</tbody></table></div><div class="invoice-total"><div class="total-row grand"><span>Quotation total</span><b>${money(q.total)}</b></div></div><div class="notice">Status: ${esc(q.status)}. This is an estimate, not a tax invoice.</div>`;showModal('Quotation',body,`${q.status!=='Converted'?`<button class="btn" onclick="closeModal();openQuotationForm(${q.id})">Edit</button><button class="btn" onclick="closeModal();convertQuotation(${q.id})">Convert to invoice</button>`:''}<button class="btn" onclick="printQuotation(${q.id})">Print / PDF</button><button class="btn" onclick="closeModal()">Close</button>`);}catch(e){toast(e.message,'error');}}
async function printQuotation(id){const w=window.open('','_blank');if(!w){toast('Allow pop-ups to print');return;}try{const q=await api('/api/quotation?id='+id);const b=state.business||{},c=q.customer;const lines=q.items.map((x,n)=>`<tr><td>${n+1}</td><td>${esc(x.description)}</td><td>${num(x.qty)}</td><td>${money(x.rate)}</td><td>${num(x.gst_rate)}%</td><td>${money(x.line_total)}</td></tr>`).join('');w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>${esc(q.quote_number)}</title><style>body{font:13px Arial;color:#19283d;margin:30px}table{width:100%;border-collapse:collapse;margin-top:22px}td,th{border:1px solid #dbe1e9;padding:9px;text-align:left}th{background:#f3f5f8}.total{text-align:right;font-size:20px;font-weight:bold;margin-top:20px}.muted{color:#64748b;font-size:11px}</style></head><body><div style="display:flex;gap:14px;align-items:center">${logoImage(b.logo_data)}<div><h1>${esc(b.name||'Business')}</h1><div class="muted">${esc(b.address||'')} · ${esc(b.phone||'')}</div></div></div><hr><h2>QUOTATION</h2><b>${esc(q.quote_number)}</b><div class="muted">Date: ${dateFmt(q.quote_date)} · Status: ${esc(q.status)}</div><p><b>Prepared for:</b> ${esc(c.name)}<br>${esc(c.address||'')}<br>${esc(c.phone||'')}</p><table><thead><tr><th>#</th><th>Description</th><th>Qty</th><th>Rate</th><th>GST</th><th>Amount</th></tr></thead><tbody>${lines}</tbody></table><div class="total">Total: ${money(q.total)}</div><p class="muted">This is a quotation / estimate, not a tax invoice. ${esc(q.notes||'')}</p><script>window.onload=()=>setTimeout(()=>window.print(),300)<\/script></body></html>`);w.document.close();}catch(e){try{w.close();}catch(_){}toast(e.message,'error');}}
function renderWarranties(){$('#warrantyTable').innerHTML=state.warranties.length?`<div class="table-wrap"><table><thead><tr><th>Warranty code</th><th>Customer</th><th>Product</th><th>Serial no.</th><th>Purchase date</th><th>Valid till</th><th>Status</th><th></th></tr></thead><tbody>${state.warranties.map(w=>`<tr><td class="strong">${esc(w.warranty_code)}</td><td>${esc(w.customer_name)}</td><td>${esc(w.product_name||'—')}</td><td>${esc(w.serial_number||'—')}</td><td>${dateFmt(w.purchase_date)}</td><td>${dateFmt(w.expiry_date)}</td><td>${new Date(w.expiry_date+'T23:59:59')>=new Date()?'<span class="status Paid">Active</span>':'<span class="status Unpaid">Expired</span>'}</td><td><button class="btn small" onclick="printWarranty(${w.id})">QR card</button></td></tr>`).join('')}</tbody></table></div>`:emptyState('No warranties registered','Register sold products to keep their serial number and warranty expiry in one place.','Register warranty','openWarrantyForm()');}
function openWarrantyForm(){if(!state.customers.length){toast('Add a customer first');openCustomerForm();return;}const body=`<form id="warrantyForm"><div class="form-grid"><div class="field"><label>Customer *</label><select name="customer_id" required><option value="">Select customer</option>${state.customers.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Product</label><select name="product_id"><option value="">Select product</option>${state.products.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></div><div class="field"><label>Serial number</label><input name="serial_number" placeholder="Product serial number"></div><div class="field"><label>Purchase date</label><input name="purchase_date" type="date" value="${today()}"></div><div class="field"><label>Warranty period (months) *</label><input name="warranty_months" type="number" min="1" max="120" value="12" required></div><div class="field"><label>Related invoice (optional)</label><select name="invoice_id"><option value="">Not linked</option>${state.invoices.map(i=>`<option value="${i.id}">${esc(i.invoice_number)} · ${esc(i.customer_name)}</option>`).join('')}</select></div><div class="field span2"><label>Notes</label><textarea name="notes"></textarea></div></div></form><div class="notice" style="margin-top:12px">HisabFlow creates a unique warranty code and a printable QR card. The QR contains the code; it does not provide a public cloud verification page in this offline edition.</div>`;showModal('Register warranty',body,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveWarranty()">Register warranty</button>`);}
async function saveWarranty(){const f=$('#warrantyForm');if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));d.customer_id=Number(d.customer_id);d.product_id=d.product_id?Number(d.product_id):null;try{const r=await api('/api/warranties',{method:'POST',body:JSON.stringify(d)});await reload();closeModal();toast(`Warranty ${r.warranty_code} registered`);}catch(e){toast(e.message,'error');}}
function printWarranty(id){const w=state.warranties.find(x=>x.id===id);if(!w)return;const win=window.open('','_blank');if(!win){toast('Allow pop-ups to print the warranty card');return;}win.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>Warranty ${esc(w.warranty_code)}</title><style>body{font:14px Arial;color:#17243a;padding:28px}.card{max-width:680px;margin:auto;border:2px solid #24385a;border-radius:16px;padding:26px;display:flex;gap:28px;align-items:center}.qr{width:170px;height:170px}.code{font-size:23px;font-weight:bold;letter-spacing:1px}.muted{color:#61718a;font-size:12px;margin:8px 0}</style></head><body><div class="card"><div>${logoImage(state.business.logo_data)}<h1>${esc(state.business.name||'HisabFlow')}</h1><div class="code">${esc(w.warranty_code)}</div><div class="muted">Customer: ${esc(w.customer_name)}</div><div class="muted">Product: ${esc(w.product_name||'—')}</div><div class="muted">Serial: ${esc(w.serial_number||'—')}</div><div class="muted">Purchase date: ${dateFmt(w.purchase_date)}</div><div class="muted">Warranty: ${w.warranty_months} months · Valid till ${dateFmt(w.expiry_date)}</div></div><img class="qr" src="${window.location.origin}/api/warranty/qr?id=${w.id}"></div><script>window.onload=()=>setTimeout(()=>window.print(),500)<\/script></body></html>`);win.document.close();}

function renderRecurring(){$('#recurringTable').innerHTML=state.recurring_templates.length?`<div class="table-wrap"><table><thead><tr><th>Template</th><th>Customer</th><th>Frequency</th><th>Next due</th><th>Status</th><th></th></tr></thead><tbody>${state.recurring_templates.map(r=>{const due=r.next_due_date<=today();return `<tr><td class="strong">${esc(r.template_name)}</td><td>${esc(r.customer_name)}</td><td>${esc(r.frequency)}</td><td>${dateFmt(r.next_due_date)}</td><td>${r.active?(due?'<span class="status Partial">Due now</span>':'<span class="status Paid">Scheduled</span>'):'<span class="status Unpaid">Paused</span>'}</td><td>${r.active&&due?`<button class="btn small primary" onclick="generateRecurring(${r.id})">Generate invoice</button>`:''} <button class="btn small danger" onclick="deleteRecurring(${r.id})">Delete</button></td></tr>`}).join('')}</tbody></table></div>`:emptyState('No recurring templates','Create one from an existing invoice for monthly, quarterly or yearly billing.','Create template','openRecurringForm()');}
async function openRecurringForm(){if(!state.invoices.length){toast('Create an invoice first; recurring templates copy an existing invoice.');openInvoiceForm();return;}const body=`<form id="recurringForm"><div class="form-grid"><div class="field span2"><label>Copy details from invoice *</label><select name="invoice_id" required>${state.invoices.map(i=>`<option value="${i.id}">${esc(i.invoice_number)} · ${esc(i.customer_name)} · ${money(i.total)}</option>`).join('')}</select></div><div class="field"><label>Template name</label><input name="template_name" value="Monthly service invoice"></div><div class="field"><label>Frequency</label><select name="frequency"><option>Monthly</option><option>Quarterly</option><option>Yearly</option><option>Weekly</option></select></div><div class="field"><label>First due date</label><input name="next_due_date" type="date" value="${today()}" required></div></div></form><div class="notice" style="margin-top:12px">This copies the selected invoice's customer and line items. Each generated invoice is saved normally and reduces tracked stock as applicable.</div>`;showModal('Create recurring template',body,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveRecurring()">Save template</button>`);}
async function saveRecurring(){const f=$('#recurringForm');if(!f.reportValidity())return;const fd=Object.fromEntries(new FormData(f));try{const inv=await api('/api/invoice?id='+fd.invoice_id);const payload={notes:inv.notes,items:inv.items.map(x=>({product_id:x.product_id,description:x.description,details:x.details||'',hsn:x.hsn,unit:x.unit,qty:x.qty,rate:x.rate,gst_rate:x.gst_rate}))};const d={template_name:fd.template_name,customer_id:inv.customer_id,frequency:fd.frequency,next_due_date:fd.next_due_date,payload};await api('/api/recurring',{method:'POST',body:JSON.stringify(d)});await reload();closeModal();toast('Recurring template saved');}catch(e){toast(e.message,'error');}}
async function generateRecurring(id){if(!confirm('Generate the due invoice now?'))return;try{const r=await api('/api/recurring/generate',{method:'POST',body:JSON.stringify({id})});await reload();toast(`Invoice ${r.invoice_number} generated`);viewInvoice(r.invoice_id);}catch(e){toast(e.message,'error');}}
async function deleteRecurring(id){if(!confirm('Delete this recurring template?'))return;try{await api('/api/recurring?id='+id,{method:'DELETE'});await reload();toast('Template deleted');}catch(e){toast(e.message,'error');}}


// Barcode and QR scanning: works with USB keyboard-wedge scanners or camera scanning in supported browsers.
function printProductQR(id){const p=state.products.find(x=>x.id===id);if(!p)return;const w=window.open('','_blank');if(!w){toast('Allow pop-ups to print a QR label');return;}w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>Product QR</title><style>body{font:14px Arial;text-align:center;padding:25px}.qr{width:190px;height:190px}h2{margin:8px}</style></head><body><img class="qr" src="${window.location.origin}/api/product/qr?id=${id}"><h2>${esc(p.name)}</h2><div>${esc(p.barcode||('Product ID '+p.id))}</div><script>window.onload=()=>setTimeout(()=>window.print(),300)<\/script></body></html>`);w.document.close();}
function cleanScannedCode(raw){let code=String(raw||'').trim();code=code.replace(/^HISABFLOW-PRODUCT:/i,'').trim();return code;}
async function scanProductCode(raw,target='invoice'){const input=target==='purchase'?$('#purchaseScanInput'):$('#invoiceScanInput');const code=cleanScannedCode(raw);if(!code)return;if(input)input.value='';try{const p=await api('/api/product/lookup?code='+encodeURIComponent(code));if(target==='purchase'){if(!$('#purchaseLines')){toast('Open a purchase bill first');return;}addPurchaseLine({product_id:p.id,description:p.name,qty:1,rate:p.purchase_rate||p.rate,gst_rate:p.gst_rate});toast('Added '+p.name+' to the purchase');$('#purchaseScanInput')?.focus();}else{if(!$('#invoiceLines')){toast('Open an invoice first');return;}addInvoiceLine({product_id:p.id,description:p.name,details:p.details||'',hsn:p.hsn,unit:p.unit,qty:1,rate:p.rate,gst_rate:p.gst_rate});toast('Added '+p.name+' to the invoice');$('#invoiceScanInput')?.focus();}}catch(e){toast(e.message,'error');(target==='purchase'?$('#purchaseScanInput'):$('#invoiceScanInput'))?.focus();}}
let activeScanStream=null,activeScanTimer=null,activeScanTarget='invoice';
function stopCameraScanner(){if(activeScanTimer){clearTimeout(activeScanTimer);activeScanTimer=null;}if(activeScanStream){activeScanStream.getTracks().forEach(t=>t.stop());activeScanStream=null;}}
async function startCameraScanner(target='invoice'){activeScanTarget=target;if(!('BarcodeDetector' in window)){toast('Camera scanning is not supported in this browser. Use a USB barcode scanner or type the code.');return;}if(!navigator.mediaDevices?.getUserMedia){toast('Camera access is unavailable. Use a USB scanner instead.');return;}showModal('Scan barcode or QR code',`<p class="tiny">Point the camera at a product barcode or HisabFlow QR label.</p><video id="scanVideo" class="scan-video" autoplay muted playsinline></video><div id="scanHint" class="tiny" style="margin-top:8px">Starting camera…</div>`,`<button class="btn" onclick="closeModal()">Cancel scan</button>`,true);try{const detector=new BarcodeDetector({formats:['qr_code','ean_13','ean_8','code_128','code_39','upc_a','upc_e','itf']});activeScanStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});const video=$('#scanVideo');video.srcObject=activeScanStream;await video.play();const detect=async()=>{if(!activeScanStream)return;try{const codes=await detector.detect(video);if(codes.length){const code=codes[0].rawValue;stopCameraScanner();closeModal();await scanProductCode(code,activeScanTarget);return;}}catch(e){}activeScanTimer=setTimeout(detect,250);};detect();}catch(e){stopCameraScanner();$('#scanHint').textContent='Could not open camera: '+e.message;toast('Camera permission or device unavailable');}}

// Cash flow combines recorded customer receipts, supplier payments, expenses, payroll and manual cash entries.
function resetCashDates(){if($('#cashFrom'))$('#cashFrom').value=monthStart();if($('#cashTo'))$('#cashTo').value=today();}
function cashFlowRows(){const list=[];state.payments.forEach(x=>list.push({date:x.payment_date,direction:'Inflow',category:'Customer receipt',description:`${x.customer_name} · ${x.invoice_number}`,method:x.method,amount:Number(x.amount),source:'Customer payment'}));state.supplier_payments.forEach(x=>list.push({date:x.payment_date,direction:'Outflow',category:'Supplier payment',description:`${x.supplier_name} · ${x.purchase_number}`,method:x.method,amount:Number(x.amount),source:'Supplier payment'}));state.expenses.forEach(x=>list.push({date:x.expense_date,direction:'Outflow',category:x.category,description:x.description,method:x.method,amount:Number(x.amount),source:'Expense'}));state.payroll_payments.forEach(x=>list.push({date:x.payment_date,direction:'Outflow',category:'Salary',description:`${x.employee_name} · ${x.payroll_month}`,method:x.method,amount:Number(x.amount),source:'Payroll'}));state.cash_entries.forEach(x=>list.push({id:x.id,date:x.entry_date,direction:x.direction,category:x.category,description:x.description,method:x.method,amount:Number(x.amount),source:'Manual'}));return list.sort((a,b)=>b.date.localeCompare(a.date));}
function renderCashFlow(){if(!$('#cashFlowTable'))return;const from=$('#cashFrom')?.value||monthStart(),to=$('#cashTo')?.value||today(),list=cashFlowRows().filter(x=>x.date>=from&&x.date<=to),inflow=list.filter(x=>x.direction==='Inflow').reduce((a,x)=>a+x.amount,0),outflow=list.filter(x=>x.direction==='Outflow').reduce((a,x)=>a+x.amount,0);$('#cashStats').innerHTML=statCard('MONEY IN',money(inflow),'Recorded inflows in this period','↗')+statCard('MONEY OUT',money(outflow),'Recorded outflows in this period','↘')+statCard('NET CASH MOVEMENT',money(inflow-outflow),'Inflow minus outflow','₹')+statCard('TRANSACTIONS',String(list.length),'Cash movements','▤');$('#cashFlowTable').innerHTML=list.length?`<div class="table-wrap"><table><thead><tr><th>Date</th><th>Type</th><th>Category</th><th>Description</th><th>Method</th><th class="right">Amount</th><th></th></tr></thead><tbody>${list.map(x=>`<tr><td>${dateFmt(x.date)}</td><td>${x.direction==='Inflow'?'<span class="status Paid">Money in</span>':'<span class="status Unpaid">Money out</span>'}</td><td>${esc(x.category)}</td><td>${esc(x.description)}</td><td>${esc(x.method)}</td><td class="right ${x.direction==='Inflow'?'cash-in':'cash-out'}">${x.direction==='Inflow'?'+':'−'}${money(x.amount)}</td><td>${x.source==='Manual'?`<button class="btn small" onclick="openCashEntryForm(${x.id})">Edit</button> <button class="btn small danger" onclick="deleteCashEntry(${x.id})">Delete</button>`:`<span class="tiny">${esc(x.source)}</span>`}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No cash movements for this date range.</div>';}
function openCashEntryForm(id=null){const x=state.cash_entries.find(r=>r.id===id)||{};const body=`<form id="cashEntryForm"><input type="hidden" name="id" value="${x.id||''}"><div class="form-grid"><div class="field"><label>Date</label><input type="date" name="entry_date" value="${x.entry_date||today()}"></div><div class="field"><label>Direction</label><select name="direction">${['Inflow','Outflow'].map(v=>`<option ${x.direction===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Category</label><select name="category">${['Owner capital','Loan received','Other income','Cash deposit','Cash withdrawal','Asset purchase','Owner drawings','Refund','Other'].map(v=>`<option ${x.category===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Amount (₹)</label><input name="amount" type="number" min="0.01" step="0.01" value="${x.amount??''}" required></div><div class="field span2"><label>Description *</label><input name="description" required value="${esc(x.description||'')}"></div><div class="field"><label>Payment method</label><select name="method">${['Cash','UPI','Bank transfer','Card','Cheque','Other'].map(v=>`<option ${x.method===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Reference</label><input name="reference" value="${esc(x.reference||'')}"></div></div></form><div class="notice" style="margin-top:12px">Use manual entries for owner capital, loan proceeds, deposits, withdrawals or other cash movements not already recorded elsewhere. Do not duplicate invoice receipts or supplier payments.</div>`;showModal(x.id?'Edit cash entry':'Add cash entry',body,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveCashEntry()">Save entry</button>`);}
async function saveCashEntry(){const f=$('#cashEntryForm');if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));try{await api('/api/cash-entries',{method:'POST',body:JSON.stringify(d)});await reload();closeModal();toast('Cash-flow entry saved');if(activeView==='cashflow')renderCashFlow();}catch(e){toast(e.message,'error');}}
async function deleteCashEntry(id){if(!confirm('Delete this manual cash-flow entry?'))return;try{await api('/api/cash-entries?id='+id,{method:'DELETE'});await reload();renderCashFlow();toast('Entry deleted');}catch(e){toast(e.message,'error');}}
function exportCashFlow(){const list=cashFlowRows();const data=[['Date','Direction','Category','Description','Method','Amount'],...list.map(x=>[x.date,x.direction,x.category,x.description,x.method,x.amount])];const csv=data.map(r=>r.map(csvCell).join(',')).join('\r\n');downloadBlob(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),'hisabflow-cash-flow.csv');}

// Staff and payroll. Salary payments are separate transactions so partial payments remain traceable.
function renderStaff(){if(!$('#staffTable'))return;const active=state.employees.filter(x=>x.active),month=state.payroll.filter(x=>x.payroll_month===today().slice(0,7)),pending=month.reduce((a,x)=>a+Number(x.balance||0),0),paid=month.reduce((a,x)=>a+Number(x.paid||0),0);$('#staffStats').innerHTML=statCard('ACTIVE STAFF',String(active.length),'Current employees','♙')+statCard('PAYROLL THIS MONTH',money(month.reduce((a,x)=>a+Number(x.net_pay),0)),'Net salary prepared','₹')+statCard('SALARY PAID',money(paid),'Payments this month','↗')+statCard('SALARY PENDING',money(pending),'Unpaid payroll balance','◷');$('#staffTable').innerHTML=state.employees.length?`<div class="table-wrap"><table><thead><tr><th>Employee</th><th>Phone</th><th>Role</th><th class="right">Monthly salary</th><th>Status</th><th></th></tr></thead><tbody>${state.employees.map(e=>`<tr><td class="strong">${esc(e.name)}</td><td>${esc(e.phone||'—')}</td><td>${esc(e.role||'—')}</td><td class="right">${money(e.monthly_salary)}</td><td>${e.active?'<span class="status Paid">Active</span>':'<span class="status Draft">Inactive</span>'}</td><td><button class="btn small" onclick="openStaffForm(${e.id})">Edit</button> ${e.active?`<button class="btn small" onclick="openPayrollForm(${e.id})">Prepare salary</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No employees added yet. Add staff members to prepare payroll.</div>';$('#payrollTable').innerHTML=state.payroll.length?`<div class="table-wrap"><table><thead><tr><th>Month</th><th>Employee</th><th class="right">Net salary</th><th class="right">Paid</th><th class="right">Balance</th><th></th></tr></thead><tbody>${state.payroll.map(x=>`<tr><td>${esc(x.payroll_month)}</td><td class="strong">${esc(x.employee_name)}</td><td class="right">${money(x.net_pay)}</td><td class="right">${money(x.paid)}</td><td class="right">${money(x.balance)}</td><td>${x.balance>.009?`<button class="btn small" onclick="paySalary(${x.id})">Pay</button>`:''} <button class="btn small" onclick="printPayslip(${x.id})">Payslip</button> <button class="btn small" onclick="openPayrollForm(null,${x.id})">Edit</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No payroll entries yet.</div>';}
function openStaffForm(id=null){const e=state.employees.find(x=>x.id===id)||{};const body=`<form id="staffForm"><input type="hidden" name="id" value="${e.id||''}"><div class="form-grid"><div class="field span2"><label>Employee name *</label><input name="name" value="${esc(e.name||'')}" required></div><div class="field"><label>Phone</label><input name="phone" value="${esc(e.phone||'')}"></div><div class="field"><label>Designation / role</label><input name="role" value="${esc(e.role||'')}"></div><div class="field"><label>Joining date</label><input type="date" name="join_date" value="${e.join_date||today()}"></div><div class="field"><label>Monthly basic salary (₹)</label><input type="number" name="monthly_salary" min="0" step="0.01" value="${e.monthly_salary??0}"></div><div class="field"><label>Status</label><select name="active"><option value="true" ${e.active!==0?'selected':''}>Active</option><option value="false" ${e.active===0?'selected':''}>Inactive</option></select></div><div class="field span2"><label>Notes</label><textarea name="notes">${esc(e.notes||'')}</textarea></div></div></form>`;showModal(e.id?'Edit employee':'Add employee',body,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveStaff()">Save employee</button>`);}
async function saveStaff(){const f=$('#staffForm');if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));d.active=d.active==='true';try{await api('/api/staff',{method:'POST',body:JSON.stringify(d)});await reload();closeModal();toast('Employee saved');}catch(e){toast(e.message,'error');}}
function openPayrollForm(employeeId=null,payrollId=null){const pr=state.payroll.find(x=>x.id===payrollId)||{},emp=state.employees.find(x=>x.id===(employeeId||pr.employee_id));const month=pr.payroll_month||today().slice(0,7);const active=state.employees.filter(x=>x.active||x.id===pr.employee_id);if(!active.length){toast('Add an active employee first');openStaffForm();return;}const body=`<form id="payrollForm"><input type="hidden" name="id" value="${pr.id||''}"><div class="form-grid"><div class="field span2"><label>Employee *</label><select name="employee_id" required onchange="updatePayrollBasic()">${active.map(e=>`<option value="${e.id}" ${Number(pr.employee_id||employeeId)===e.id?'selected':''}>${esc(e.name)}</option>`).join('')}</select></div><div class="field"><label>Payroll month</label><input type="month" name="payroll_month" value="${month}" required></div><div class="field"><label>Basic salary (₹)</label><input id="payrollBasic" type="number" name="basic_salary" min="0" step="0.01" value="${pr.basic_salary??emp?.monthly_salary??0}" required></div><div class="field"><label>Allowances (₹)</label><input type="number" name="allowances" min="0" step="0.01" value="${pr.allowances??0}"></div><div class="field"><label>Deductions (₹)</label><input type="number" name="deductions" min="0" step="0.01" value="${pr.deductions??0}"></div><div class="field span2"><label>Notes</label><textarea name="notes">${esc(pr.notes||'')}</textarea></div></div><div class="notice" style="margin-top:12px">Net salary = basic salary + allowances − deductions. This is a simple payroll register, not statutory payroll processing or automated TDS/PF/ESI compliance.</div></form>`;showModal(pr.id?'Edit payroll entry':'Prepare monthly payroll',body,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="savePayroll()">Save payroll</button>`);}
function updatePayrollBasic(){const f=$('#payrollForm');if(!f)return;const emp=state.employees.find(x=>x.id===Number(f.elements.employee_id.value));if(emp)$('#payrollBasic').value=emp.monthly_salary;}
async function savePayroll(){const f=$('#payrollForm');if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));d.employee_id=Number(d.employee_id);try{await api('/api/payroll',{method:'POST',body:JSON.stringify(d)});await reload();closeModal();toast('Payroll entry saved');}catch(e){toast(e.message,'error');}}
function paySalary(id){const pr=state.payroll.find(x=>x.id===id);if(!pr||pr.balance<=.009)return;const body=`<form id="salaryPaymentForm"><input type="hidden" name="payroll_id" value="${id}"><div class="notice">${esc(pr.employee_name)} · ${esc(pr.payroll_month)}<br>Salary balance: <b>${money(pr.balance)}</b></div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Payment date</label><input name="payment_date" type="date" value="${today()}"></div><div class="field"><label>Amount (₹)</label><input name="amount" type="number" min="0.01" step="0.01" max="${pr.balance}" value="${pr.balance.toFixed(2)}" required></div><div class="field"><label>Method</label><select name="method"><option>Bank transfer</option><option>Cash</option><option>UPI</option><option>Cheque</option></select></div><div class="field"><label>Reference</label><input name="reference"></div></div></form>`;showModal('Pay employee salary',body,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveSalaryPayment()">Record payment</button>`);}
async function saveSalaryPayment(){const f=$('#salaryPaymentForm');if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));d.payroll_id=Number(d.payroll_id);try{await api('/api/payroll/payment',{method:'POST',body:JSON.stringify(d)});await reload();closeModal();toast('Salary payment recorded');}catch(e){toast(e.message,'error');}}
async function printPayslip(id){const pr=state.payroll.find(x=>x.id===id);if(!pr)return;const w=window.open('','_blank');if(!w){toast('Allow pop-ups to print payslip');return;}const b=state.business||{};w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>Salary slip</title><style>body{font:14px Arial;padding:28px;color:#182438}.logo{max-width:110px;max-height:70px}table{width:100%;border-collapse:collapse;margin-top:20px}td{border:1px solid #dfe5ed;padding:10px}.total{font-size:20px;font-weight:bold;text-align:right;margin-top:18px}</style></head><body>${logoImage(b.logo_data,'logo')}<h1>${esc(b.name||'Business')}</h1><h2>Salary slip · ${esc(pr.payroll_month)}</h2><p>Employee: <b>${esc(pr.employee_name)}</b><br>Designation: ${esc(pr.role||'—')}</p><table><tr><td>Basic salary</td><td>${money(pr.basic_salary)}</td></tr><tr><td>Allowances</td><td>${money(pr.allowances)}</td></tr><tr><td>Deductions</td><td>− ${money(pr.deductions)}</td></tr><tr><td>Paid</td><td>${money(pr.paid)}</td></tr><tr><td>Balance pending</td><td>${money(pr.balance)}</td></tr></table><div class="total">Net salary: ${money(pr.net_pay)}</div><p style="font-size:11px;color:#64748b">Generated by HisabFlow. This is a salary record, not a statutory payslip.</p><script>window.onload=()=>setTimeout(()=>window.print(),250)<\/script></body></html>`);w.document.close();}

// Local business assistant: reports and deterministic insights, with optional browser speech-to-text input.
function renderAssistantInsights(){if(!$('#aiInsights'))return;const low=state.products.filter(p=>p.track_stock&&Number(p.stock_qty)<=Number(p.low_stock_level));const dues=state.invoices.filter(i=>i.balance>0.009).sort((a,b)=>b.balance-a.balance);const nowSales=state.invoices.filter(i=>i.invoice_date>=monthStart()).reduce((a,i)=>a+i.total,0);const lastMonthStart=isoLocal(new Date(new Date().getFullYear(),new Date().getMonth()-1,1));const lastMonthEnd=isoLocal(new Date(new Date().getFullYear(),new Date().getMonth(),0));const lastSales=state.invoices.filter(i=>i.invoice_date>=lastMonthStart&&i.invoice_date<=lastMonthEnd).reduce((a,i)=>a+i.total,0);const insights=[];if(low.length)insights.push(`<div class="ai-alert"><b>⚠ ${low.length} low-stock item(s)</b><div class="tiny">${low.slice(0,4).map(x=>esc(x.name)+' ('+num(x.stock_qty)+' '+esc(x.unit)+')').join(', ')}</div></div>`);if(dues.length)insights.push(`<div class="ai-alert"><b>₹${num(dues.reduce((a,x)=>a+x.balance,0))} customer dues</b><div class="tiny">Largest balance: ${esc(dues[0].customer_name)} · ${money(dues[0].balance)}</div></div>`);if(lastSales>0)insights.push(`<div class="ai-alert"><b>Monthly sales comparison</b><div class="tiny">Current month ${money(nowSales)} · Previous month ${money(lastSales)} · ${nowSales>=lastSales?'currently ahead':'currently below'} the previous month total.</div></div>`);if(!insights.length)insights.push('<div class="tiny">No urgent alerts. Add invoices, stock and payment records to unlock more insights.</div>');$('#aiInsights').innerHTML=insights.join('');}
function addAIMessage(text,who='bot'){const chat=$('#aiChat');const el=document.createElement('div');el.className='ai-message '+who;el.textContent=text;chat.appendChild(el);chat.scrollTop=chat.scrollHeight;}
async function askAssistant(question=null){const input=$('#aiPrompt');const prompt=(question??input?.value??'').trim();if(!prompt)return;if(input)input.value='';addAIMessage(prompt,'user');try{const r=await api('/api/assistant',{method:'POST',body:JSON.stringify({prompt})});addAIMessage(r.answer+'\n\n'+r.engine+' · '+r.privacy,'bot');}catch(e){addAIMessage('I could not answer that: '+e.message,'bot');}}
$('#aiForm')?.addEventListener('submit',e=>{e.preventDefault();askAssistant();});
function startVoiceQuestion(){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){toast('Voice recognition is not supported here. Try current Chrome or Edge.');return;}const r=new SR();r.lang=$('#aiVoiceLang').value||'en-IN';r.interimResults=false;r.maxAlternatives=1;r.onstart=()=>toast('Listening… speak your business question');r.onerror=e=>toast('Voice input: '+e.error);r.onresult=e=>{const phrase=e.results?.[0]?.[0]?.transcript||'';$('#aiPrompt').value=phrase;askAssistant(phrase);};r.start();}
function suggestExpenseCategory(value){const f=$('#expenseForm');if(!f)return;const t=value.toLowerCase(),sel=f.elements.category;const rules=[['rent','Rent'],['salary','Salary / wages'],['wage','Salary / wages'],['electric','Electricity'],['fuel','Transport / fuel'],['petrol','Transport / fuel'],['transport','Transport / fuel'],['repair','Repairs'],['internet','Telephone / internet'],['phone','Telephone / internet'],['marketing','Marketing'],['advert','Marketing'],['stationery','Office supplies'],['bank','Bank charges']];const hit=rules.find(([k])=>t.includes(k));if(hit)sel.value=hit[1];}

function openCustomerLedger(id){const c=state.customers.find(x=>x.id===id);if(!c)return;const inv=state.invoices.filter(i=>i.customer_id===id),due=inv.reduce((a,i)=>a+i.balance,0),paid=state.payments.filter(p=>inv.some(i=>i.id===p.invoice_id)).reduce((a,p)=>a+p.amount,0);const body=`<div class="grid stats" style="grid-template-columns:repeat(3,1fr)">${statCard('INVOICED',money(inv.reduce((a,i)=>a+i.total,0)),'Customer billing','▤')}${statCard('PAID',money(paid),'Payments received','₹')}${statCard('OUTSTANDING',money(due),'Customer udhaari','◷')}</div><div class="panel"><div class="panel-head"><b>${esc(c.name)} · Ledger</b><span class="tiny">${esc(c.phone||'')}</span></div><div class="table-wrap"><table><thead><tr><th>Invoice</th><th>Date</th><th class="right">Amount</th><th class="right">Paid</th><th class="right">Balance</th><th></th></tr></thead><tbody>${inv.map(i=>`<tr><td>${esc(i.invoice_number)}</td><td>${dateFmt(i.invoice_date)}</td><td class="right">${money(i.total)}</td><td class="right">${money(i.paid)}</td><td class="right strong">${money(i.balance)}</td><td><button class="btn small" onclick="viewInvoice(${i.id})">View</button></td></tr>`).join('')||'<tr><td colspan="6">No invoices for this customer.</td></tr>'}</tbody></table></div></div>`;showModal('Customer ledger',body,`<button class="btn" onclick="closeModal()">Close</button>${c.phone?`<button class="btn primary" onclick="sendCustomerReminder(${c.id})">WhatsApp statement</button>`:''}`,true);}
function waOpen(phone,message){const digits=String(phone||'').replace(/\D/g,'');if(!digits){toast('Add a phone number to this contact first');return;}const full=digits.length===10?'91'+digits:digits;window.open('https://wa.me/'+full+'?text='+encodeURIComponent(message),'_blank','noopener');}
function sendInvoiceReminder(id){const i=state.invoices.find(x=>x.id===id);if(!i)return;const msg=`Hello ${i.customer_name}, this is a friendly payment reminder for invoice ${i.invoice_number}. Outstanding amount: ${money(i.balance)}. Please let us know once paid. Thank you, ${state.business.name||'our team'}.`;waOpen(i.customer_phone,msg);}
function sendCustomerReminder(id){const c=state.customers.find(x=>x.id===id);if(!c)return;const invoices=state.invoices.filter(i=>i.customer_id===id&&i.balance>.009);const total=invoices.reduce((a,i)=>a+i.balance,0);const detail=invoices.map(i=>`${i.invoice_number}: ${money(i.balance)}`).join('\n');waOpen(c.phone,`Hello ${c.name}, your outstanding balance with ${state.business.name||'our business'} is ${money(total)}.\n${detail}\nPlease contact us for any clarification. Thank you.`);}
function shareInvoiceWhatsApp(id){const inv=state.invoices.find(x=>x.id===id);if(!inv)return;waOpen(inv.customer_phone,`Hello ${inv.customer_name}, your invoice ${inv.invoice_number} dated ${dateFmt(inv.invoice_date)} is for ${money(inv.total)}. Paid: ${money(inv.paid)}. Balance: ${money(inv.balance)}. Thank you, ${state.business.name}.`);}
function sendDailySummary(){const sales=state.invoices.filter(i=>i.invoice_date===today()).reduce((a,i)=>a+i.total,0),collected=state.payments.filter(p=>p.payment_date===today()).reduce((a,p)=>a+p.amount,0),exp=state.expenses.filter(e=>e.expense_date===today()).reduce((a,e)=>a+e.amount,0);const msg=`Daily business summary · ${dateFmt(today())}\nSales: ${money(sales)}\nCollections: ${money(collected)}\nExpenses: ${money(exp)}\nLow stock items: ${state.products.filter(p=>p.track_stock&&p.stock_qty<=p.low_stock_level).length}`;const b=state.business||{};if(!b.phone){toast('Add your business phone in settings to open WhatsApp');return;}waOpen(b.phone,msg);}


// Populate business state selector and initialise the app.
$$('.nav-btn[data-view]').forEach(b=>b.addEventListener('click',()=>{navigate(b.dataset.view);window.scrollTo({top:0});}));
// ---------------------------------------------------------------- Sign-in (offline, local accounts)
let currentUser=null,authMode='login',appStarted=false;
const isOwner=()=>currentUser?.role==='owner';
function initials(u){const n=(u?.display_name||u?.username||'?').trim().split(/\s+/);return ((n[0]?.[0]||'')+(n[1]?.[0]||'')).toUpperCase()||'?';}
function showAuth(mode='login',message=''){authMode=mode;const setup=mode==='setup';$('#authScreen').classList.add('show');document.body.style.overflow='hidden';$$('.setup-only').forEach(x=>x.classList.toggle('hide',!setup));$('#authTitle').textContent=setup?'Create your owner account':'Sign in';$('#authSub').textContent=setup?'First-time setup. This account will own the business data on this computer.':'Welcome back! Enter your details to continue.';$('#authSubmit').textContent=setup?'Create account & continue':'Sign in';$('#authPass').autocomplete=setup?'new-password':'current-password';$('#authPass').placeholder=setup?'At least 6 characters':'Enter password';$('#authHelp').innerHTML=setup?'Choose a password you will remember. There is no email reset because HisabFlow works offline. If you ever forget it, run <code>python app.py --reset-password USERNAME</code> in the HisabFlow folder on this computer.':'Forgot your password? Ask the owner to reset it from <b>Settings → Users & access</b>, or on this computer run <code>python app.py --reset-password USERNAME</code> in the HisabFlow folder.';setAuthError(message);$('#authPass').value='';if($('#authPass2'))$('#authPass2').value='';setTimeout(()=>(setup?$('#authDisplay'):($('#authUser').value?$('#authPass'):$('#authUser'))).focus(),50);}
function hideAuth(){$('#authScreen').classList.remove('show');document.body.style.overflow='';}
function setAuthError(msg){const el=$('#authError');el.textContent=msg||'';el.classList.toggle('show',!!msg);}
function togglePw(id,btn){const i=document.getElementById(id);i.type=i.type==='password'?'text':'password';btn.textContent=i.type==='password'?'Show':'Hide';}
function pwScore(p){let s=0;if(p.length>=6)s++;if(p.length>=10)s++;if(/[A-Z]/.test(p)&&/[a-z]/.test(p))s++;if(/\d/.test(p))s++;if(/[^A-Za-z0-9]/.test(p))s++;return s;}
$('#authPass').addEventListener('input',e=>{if(authMode!=='setup')return;const sc=pwScore(e.target.value),m=$('#pwMeter');m.style.width=(sc*20)+'%';m.style.background=sc<=1?'#f43f5e':sc<=3?'#f59e0b':'#10b981';});
$('#authForm').addEventListener('submit',async e=>{e.preventDefault();setAuthError('');const f=e.target,username=f.username.value.trim(),password=f.password.value,remember=f.remember.checked;if(!username||!password){setAuthError('Enter your username and password.');return;}if(authMode==='setup'){if(password.length<6){setAuthError('Password must be at least 6 characters.');return;}if(password!==f.password2.value){setAuthError('The two passwords do not match.');return;}}const btn=$('#authSubmit'),label=btn.textContent;btn.disabled=true;btn.textContent='Please wait…';try{const r=await api(authMode==='setup'?'/api/auth/setup':'/api/auth/login',{method:'POST',body:JSON.stringify({username,password,remember,display_name:f.display_name.value.trim()})});currentUser=r.user;hideAuth();f.password.value='';await startApp();toast(authMode==='setup'?'Owner account created. Welcome!':`Welcome back, ${currentUser.display_name||currentUser.username}`);}catch(err){setAuthError(err.message);}finally{btn.disabled=false;btn.textContent=label;}});
function renderUser(){const u=currentUser||{};$('#userAvatar').textContent=initials(u);$('#userName').textContent=u.display_name||u.username||'Account';$('#userMenuName').textContent=u.display_name||u.username||'';$('#userMenuRole').innerHTML=`@${esc(u.username||'')} · <span class="role-pill ${esc(u.role||'')}">${esc(u.role||'')}</span>`;if($('#settingsUser'))$('#settingsUser').textContent=`${u.display_name||u.username} (@${u.username}, ${u.role})`;document.body.classList.toggle('is-staff',u.role!=='owner');$$('.owner-only').forEach(x=>x.classList.toggle('hide',u.role!=='owner'));$$('.staff-only').forEach(x=>x.classList.toggle('hide',u.role==='owner'));$$('#businessForm input,#businessForm select,#businessForm textarea').forEach(x=>x.disabled=u.role!=='owner');}
function toggleUserMenu(e){e.stopPropagation();$('#userMenu').classList.toggle('show');}
function closeUserMenu(){$('#userMenu')?.classList.remove('show');}
document.addEventListener('click',e=>{if(!e.target.closest('.user-chip'))closeUserMenu();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeUserMenu();if($('#modalBackdrop').classList.contains('show')&&!$('#authScreen').classList.contains('show'))closeModal();}});
async function logout(){closeUserMenu();try{await api('/api/auth/logout',{method:'POST',body:'{}'});}catch(_){}currentUser=null;closeModal();$('#authUser').value='';showAuth('login','');toast('You have been signed out');}
function openChangePassword(){const body=`<form id="pwForm" autocomplete="off"><div class="form-grid"><div class="field span2"><label>Current password *</label><input type="password" name="current_password" required autocomplete="current-password"></div><div class="field"><label>New password *</label><input type="password" name="new_password" minlength="6" required autocomplete="new-password"></div><div class="field"><label>Confirm new password *</label><input type="password" name="confirm" minlength="6" required autocomplete="new-password"></div></div><div class="notice info-note" style="margin-top:12px">Other devices or browser windows signed in to your account will be signed out.</div></form>`;showModal('Change password',body,`<button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveChangePassword()">Update password</button>`);}
async function saveChangePassword(){const f=$('#pwForm');if(!f.reportValidity())return;if(f.new_password.value!==f.confirm.value){toast('New passwords do not match','error');return;}try{await api('/api/auth/change-password',{method:'POST',body:JSON.stringify({current_password:f.current_password.value,new_password:f.new_password.value})});closeModal();toast('Password updated');}catch(e){toast(e.message,'error');}}
let usersCache=[];
async function renderUsers(){if(!isOwner()||!$('#usersList'))return;try{usersCache=await api('/api/users');$('#usersList').innerHTML=usersCache.map(u=>`<div class="user-row"><span class="avatar" style="${u.active?'':'filter:grayscale(1);opacity:.6'}">${esc(initials(u))}</span><div class="grow"><b>${esc(u.display_name||u.username)}</b> <span class="role-pill ${esc(u.role)}">${esc(u.role)}</span>${u.active?'':' <span class="status Draft">Disabled</span>'}<span class="tiny">@${esc(u.username)} · ${u.last_login?'Last sign-in '+esc(u.last_login.replace('T',' ').slice(0,16)):'Never signed in'}</span></div><button class="btn small" onclick="openUserForm(${u.id})">Edit</button></div>`).join('')||'<div class="empty-inline">No users.</div>';}catch(e){$('#usersList').innerHTML=`<div class="empty-inline">${esc(e.message)}</div>`;}}
function openUserForm(id=null){const u=usersCache.find(x=>x.id===id)||{};const self=u.id===currentUser?.id;const body=`<form id="userForm" autocomplete="off"><input type="hidden" name="id" value="${u.id||''}"><div class="form-grid"><div class="field"><label>Username *</label><input name="username" value="${esc(u.username||'')}" ${u.id?'disabled':''} required pattern="[A-Za-z0-9_.@\\-]{3,40}" placeholder="e.g. cashier1" autocapitalize="off"></div><div class="field"><label>Display name</label><input name="display_name" value="${esc(u.display_name||'')}" placeholder="e.g. Priya"></div><div class="field"><label>Role</label><select name="role" ${self?'disabled':''}><option value="staff" ${u.role!=='owner'?'selected':''}>Staff — billing & daily entries</option><option value="owner" ${u.role==='owner'?'selected':''}>Owner — full access</option></select></div><div class="field"><label>Status</label><select name="active" ${self?'disabled':''}><option value="true" ${u.active!==0?'selected':''}>Active — can sign in</option><option value="false" ${u.active===0?'selected':''}>Disabled — cannot sign in</option></select></div><div class="field span2"><label>${u.id?'Reset password (leave blank to keep current)':'Password *'}</label><input name="password" type="password" minlength="6" ${u.id?'':'required'} autocomplete="new-password" placeholder="At least 6 characters"></div></div>${self?'<div class="notice info-note" style="margin-top:12px">This is your own account. Use “Change password” from the account menu to change your password.</div>':''}</form>`;showModal(u.id?'Edit user':'Add user',body,`${u.id&&!self?`<button class="btn danger" onclick="deleteUser(${u.id})">Delete</button>`:''}<span style="flex:1"></span><button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" onclick="saveUser()">Save user</button>`);}
async function saveUser(){const f=$('#userForm');if(!f.reportValidity())return;const id=f.id.value;const self=Number(id)===currentUser?.id;const d={id:id?Number(id):null,username:f.username.value.trim(),display_name:f.display_name.value.trim(),role:self?'owner':f.role.value,active:self?true:f.active.value==='true',password:self?'':f.password.value};try{await api('/api/users',{method:'POST',body:JSON.stringify(d)});closeModal();await renderUsers();if(self){currentUser={...currentUser,display_name:d.display_name||currentUser.username};renderUser();}toast('User saved');}catch(e){toast(e.message,'error');}}
async function deleteUser(id){if(!confirm('Delete this user? They will no longer be able to sign in. Business records they created are kept.'))return;try{await api('/api/users/delete',{method:'POST',body:JSON.stringify({id})});closeModal();await renderUsers();toast('User deleted');}catch(e){toast(e.message,'error');}}
async function startApp(){const s=await api('/api/state');state=s;if(!appStarted){$('#businessState').innerHTML='<option value="">Select state</option>'+state.states.map(x=>`<option>${esc(x)}</option>`).join('');resetReportDates();resetCashDates();appStarted=true;}renderUser();renderAll();fillBusinessForm();renderUser();renderUsers();if(!state.business?.name&&isOwner())navigate('settings');}
// App start-up lives in features.js (boot).
